def _parse_step(path, i):
    n = len(path)
    if path.startswith("..", i):
        m = _NAME_RE.match(path, i + 2)
        if m is None:
            return None, None
        return ("desc", m.group()), m.end()
    c = path[i]
    if c == '.':
        m = _NAME_RE.match(path, i + 1)
        if m is None:
            return None, None
        return ("key", m.group()), m.end()
    if c == '[':
        if i + 1 >= n:
            return None, None
        nxt = path[i + 1]
        if nxt == '*':
            if i + 2 < n and path[i + 2] == ']':
                return ("star", None), i + 3
            return None, None
        if nxt == "'":
            j = i + 2
            buf = []
            while j < n:
                ch = path[j]
                if ch == "'":
                    if j + 1 < n and path[j + 1] == ']':
                        return ("key", "".join(buf)), j + 2
                    return None, None
                if ch == '\\':
                    if j + 1 >= n:
                        return None, None
                    esc = path[j + 1]
                    if esc == "'":
                        buf.append("'")
                    elif esc == '\\':
                        buf.append('\\')
                    else:
                        return None, None
                    j += 2
                    continue
                buf.append(ch)
                j += 1
            return None, None
        if nxt == '-' or ('0' <= nxt <= '9'):
            j = i + 1
            negative = False
            if path[j] == '-':
