                return None, None
            if len(digits) > 1 and digits[0] == '0':
                return None, None
            if j >= n or path[j] != ']':
                return None, None
            value = int(digits)
            if negative:
                value = -value
            return ("index", value), j + 1
        return None, None
    return None, None

def _apply_step(step, v):
    kind, arg = step
    if kind == "key":
        if isinstance(v, dict) and arg in v:
            return [v[arg]]
        return []
    if kind == "index":
        if isinstance(v, list):
            length = len(v)
            if arg >= 0:
                if arg < length:
                    return [v[arg]]
            else:
                idx = length + arg
                if 0 <= idx < length:
                    return [v[idx]]
        return []
    if kind == "star":
        if isinstance(v, list):
            return list(v)
        if isinstance(v, dict):
            return list(v.values())
        return []
    if kind == "desc":
        res = []
        stack = [v]
        while stack:
            cur = stack.pop()
            if isinstance(cur, dict):
                if arg in cur:
                    res.append(cur[arg])
                for val in reversed(list(cur.values())):
                    stack.append(val)
            elif isinstance(cur, list):
                for item in reversed(cur):
                    stack.append(item)
        return res
    return []

