_IDENT_RE = re.compile(r'[A-Za-z_][A-Za-z0-9_]*')


def _parse_bracket(path, i):
    n = len(path)
    j = i + 1
    if j >= n:
        return None
    c = path[j]
    if c == '*':
        if j + 1 < n and path[j + 1] == ']':
            return ('all',), j + 2
        return None
    if c == "'":
        j += 1
        buf = []
        while True:
            if j >= n:
                return None
            ch = path[j]
            if ch == '\\':
                if j + 1 >= n:
                    return None
                nxt = path[j + 1]
                if nxt == "'":
                    buf.append("'")
                    j += 2
                elif nxt == '\\':
                    buf.append('\\')
                    j += 2
                else:
                    return None
            elif ch == "'":
                j += 1
                break
            else:
                buf.append(ch)
                j += 1
        if j >= n or path[j] != ']':
            return None
        return ('key', ''.join(buf)), j + 1
    k = j
    neg = False
    if path[k] == '-':
        neg = True
        k += 1
    start = k
    while k < n and '0' <= path[k] <= '9':
        k += 1
    digits = path[start:k]
    if not digits:
        return None
    if len(digits) > 1 and digits[0] == '0':
        return None
    if k >= n or path[k] != ']':
        return None
    val = int(('-' if neg else '') + digits)
    return ('index', val), k + 1


def _parse_path(path):
    if not isinstance(path, str) or not path.startswith('$'):
        return None
    steps = []
    i = 1
    n = len(path)
    while i < n:
        c = path[i]
        if c == '.':
            if path.startswith('..', i):
                m = _IDENT_RE.match(path, i + 2)
                if m is None:
                    return None
                steps.append(('recurse', m.group(0)))
                i = m.end()
            else:
                m = _IDENT_RE.match(path, i + 1)
                if m is None:
                    return None
                steps.append(('key', m.group(0)))
                i = m.end()
        elif c == '[':
            r = _parse_bracket(path, i)
            if r is None:
                return None
            step, i = r
            steps.append(step)
        else:
            return None
    return steps


def _collect_recursive(v, key, out):
    stack = [v]
    while stack:
        cur = stack.pop()
        if isinstance(cur, dict):
            if key in cur:
                out.append(cur[key])
            for val in reversed(list(cur.values())):
                stack.append(val)
        elif isinstance(cur, list):
            for val in reversed(cur):
                stack.append(val)


