            return None
    n = len(headers)
    for row in rows:
        if len(row) > n:
            return None

    def cell_text(v):
        return str(v).replace('|', '\\|')

    header_texts = [cell_text(h) for h in headers]

    padded_rows = []
    for row in rows:
        cells = [cell_text(v) for v in row]
        if len(cells) < n:
            cells = cells + [''] * (n - len(cells))
        padded_rows.append(cells)

    widths = []
    for i in range(n):
