    def advance():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def add_poly(a, b):
        r = dict(a)
        for d, c in b.items():
            nc = r.get(d, 0) + c
            if nc == 0:
                r.pop(d, None)
            else:
                r[d] = nc
        return r

    def neg_poly(a):
        return {d: -c for d, c in a.items()}

    def mul_poly(a, b):
        r = {}
        for d1, c1 in a.items():
            for d2, c2 in b.items():
                d = d1 + d2
                nc = r.get(d, 0) + c1 * c2
                if nc == 0:
                    r.pop(d, None)
                else:
                    r[d] = nc
        return r

    def pow_poly(a, e):
        r = {0: 1}
        for _ in range(e):
            r = mul_poly(r, a)
        return r

    def parse_expr():
        p = parse_term()
        while peek() == '+' or peek() == '-':
            op = advance()[0]
