    def parse_base():
        t = peek()
        if t == 'int':
            tok = advance()
            v = int(tok[1])
            if v == 0:
                return {}
            return {0: v}
        if t == 'x':
            advance()
            return {1: 1}
        if t == '(':
            advance()
            p = parse_expr()
            if peek() != ')':
                raise ParseError()
            advance()
            return p
        raise ParseError()

    try:
        if len(tokens) == 0:
            return None
        result = parse_expr()
        if pos != len(tokens):
            return None
    except ParseError:
        return None

    if not result:
        return '0'

    out = []
    first = True
    for d in sorted(result, reverse=True):
        c = result[d]
        ac = abs(c)
        if d == 0:
            body = str(ac)
        else:
            body = ('' if ac == 1 else str(ac)) + 'x'
            if d > 1:
                body += '^' + str(d)
        if first:
            out.append(('-' if c < 0 else '') + body)
            first = False
        else:
            out.append(('+' if c > 0 else '-') + body)
    return ''.join(out)

