import re
from datetime import datetime, date, timedelta

_ITEM_RE = re.compile(r'^(\*|[0-9]+(?:-[0-9]+)?)(?:/([0-9]+))?$')
_START_RE = re.compile(r'^([0-9]{4})-([0-9]{2})-([0-9]{2}) ([0-9]{2}):([0-9]{2})$')


def _parse_field(text, lo, hi):
    if text == '*':
        return None, False
    if text == '':
        return None
    values = set()
    for item in text.split(','):
        m = _ITEM_RE.match(item)
        if m is None:
            return None
        rng = m.group(1)
        step_s = m.group(2)
        step = int(step_s) if step_s is not None else 1
        if step < 1:
            return None
        if rng == '*':
            for v in range(lo, hi + 1, step):
                values.add(v)
            continue
        if '-' in rng:
            a_s, b_s = rng.split('-')
            n = int(a_s)
            m2 = int(b_s)
            if n > m2 or n < lo or m2 > hi:
                return None
            for v in range(n, m2 + 1, step):
                values.add(v)
            continue
        n = int(rng)
        if n < lo or n > hi:
            return None
        if step_s is None:
            values.add(n)
        else:
            for v in range(n, hi + 1, step):
                values.add(v)
    if not values:
        return None
    return values, True


def _parse_start(start):
    m = _START_RE.match(start)
    if m is None:
        return None
    try:
        return datetime(int(m.group(1)), int(m.group(2)), int(m.group(3)),
                        int(m.group(4)), int(m.group(5)))
    except ValueError:
        return None


