    if len(parts) != 5:
        return None
    ranges = ((0, 59), (0, 23), (1, 31), (1, 12), (0, 6))
    parsed = []
    for text, (lo, hi) in zip(parts, ranges):
        res = _parse_field(text, lo, hi)
        if res is None:
            return None
        parsed.append(res)
    minute_vals = parsed[0][0]
    hour_vals = parsed[1][0]
    dom_vals, dom_restr = parsed[2]
    month_vals = parsed[3][0]
    dow_vals, dow_restr = parsed[4]
    st = _parse_start(start)
    if st is None:
        return None
    end_year = min(st.year + 4, 9999)
    end_date = date(end_year, 12, 31)
