    def is_digits(s):
        return isinstance(s, str) and len(s) > 0 and all('0' <= c <= '9' for c in s)

    def parse_field(text, lo, hi):
        restricted = text != '*'
        values = set()
        for item in text.split(','):
            if item == '':
                return None
            if '/' in item:
                parts = item.split('/')
                if len(parts) != 2:
                    return None
                left, step_text = parts
                if not is_digits(step_text):
                    return None
                step = int(step_text)
                if step < 1:
                    return None
            else:
                left = item
                step = None

            if left == '*':
                if step is None:
                    values.update(range(lo, hi + 1))
                else:
                    values.update(range(lo, hi + 1, step))
                continue

            if '-' in left:
                parts = left.split('-')
                if len(parts) != 2:
                    return None
                a_text, b_text = parts
                if not is_digits(a_text) or not is_digits(b_text):
                    return None
                a = int(a_text)
                b = int(b_text)
                if a < lo or a > hi or b < lo or b > hi:
                    return None
                if a > b:
                    return None
                if step is None:
                    values.update(range(a, b + 1))
                else:
                    values.update(range(a, b + 1, step))
            else:
                if not is_digits(left):
                    return None
                a = int(left)
                if a < lo or a > hi:
                    return None
                if step is None:
                    values.add(a)
                else:
                    values.update(range(a, hi + 1, step))

        if not values:
            return None
        return values, restricted

    fields = expr.split(' ')
    if len(fields) != 5 or any(f == '' for f in fields):
        return None

    parsed = []
    for text, (lo, hi) in zip(fields, [(0, 59), (0, 23), (1, 31), (1, 12), (0, 6)]):
        r = parse_field(text, lo, hi)
        if r is None:
            return None
        parsed.append(r)

    minute_vals, _ = parsed[0]
    hour_vals, _ = parsed[1]
    dom_vals, dom_restricted = parsed[2]
    month_vals, _ = parsed[3]
    dow_vals, dow_restricted = parsed[4]

    if len(start) != 16:
        return None
    if start[4] != '-' or start[7] != '-' or start[10] != ' ' or start[13] != ':':
        return None
    if not is_digits(start[:4]) or not is_digits(start[5:7]) or not is_digits(start[8:10]) or not is_digits(start[11:13]) or not is_digits(start[14:16]):
        return None

    y = int(start[:4])
    mo = int(start[5:7])
    d = int(start[8:10])
    h = int(start[11:13])
    mi = int(start[14:16])

    if not (1 <= y <= 9999 and 1 <= mo <= 12 and 0 <= h <= 23 and 0 <= mi <= 59):
        return None
    try:
        start_date = date(y, mo, d)
    except ValueError:
        return None
    start_dt = datetime(y, mo, d, h, mi)

    horizon_year = min(y + 5, 10000)
    end_date = date(horizon_year - 1, 12, 31)

    total_days = (end_date - start_date).days + 1
    for i in range(total_days):
        day = start_date + __import__('datetime').timedelta(days=i)
        if day.month not in month_vals:
            continue
        weekday = (day.weekday() + 1) % 7
        dom_match = day.day in dom_vals
        dow_match = weekday in dow_vals
        if dom_restricted and dow_restricted:
            if not (dom_match or dow_match):
                continue
        else:
            if not (dom_match and dow_match):
                continue
        for hh in sorted(hour_vals):
            for mm in sorted(minute_vals):
                cand = datetime(day.year, day.month, day.day, hh, mm)
                if cand > start_dt:
                    return cand.strftime('%Y-%m-%d %H:%M')
    return None

