def rational_eval(expr):
    try:
        if not isinstance(expr, str):
            return 'error'
        tokens = []
        i = 0
        n = len(expr)
        while i < n:
            c = expr[i]
            if c == ' ' or c == '\t':
                i += 1
            elif '0' <= c <= '9':
                j = i
                while j < n and '0' <= expr[j] <= '9':
                    j += 1
                tokens.append(expr[i:j])
                i = j
            elif c in ('+', '-', '*', '/', '^', '(', ')'):
                tokens.append(c)
                i += 1
            else:
                return 'error'
        pos = 0

        def peek():
            return tokens[pos] if pos < len(tokens) else None

        def parse_expr():
            nonlocal pos
            value = parse_term()
            while peek() in ('+', '-'):
                op = tokens[pos]
                pos += 1
                rhs = parse_term()
                value = value + rhs if op == '+' else value - rhs
            return value

        def parse_term():
            nonlocal pos
            value = parse_unary()
            while peek() in ('*', '/'):
                op = tokens[pos]
                pos += 1
                rhs = parse_unary()
                if op == '*':
                    value = value * rhs
                else:
                    if rhs == 0:
                        raise ValueError('division by zero')
                    value = value / rhs
