                val = tokens[pos][1]
                advance()
                return (val, 1)
            if t == '(':
                advance()
                node = parse_expr()
                if peek() != ')':
                    raise _Error
                advance()
                return node
            raise _Error

        def parse_power():
            base = parse_atom()
            if peek() == '^':
                advance()
                exp = parse_unary()
                return norm_pow(base, exp)
            return base

        def parse_unary():
            if peek() == '-':
                advance()
                node = parse_unary()
                return (-node[0], node[1])
            return parse_power()

        def parse_term():
            node = parse_unary()
            while peek() == '*' or peek() == '/':
                op = advance()[0]
                rhs = parse_unary()
                if op == '*':
                    node = norm_mul(node, rhs)
                else:
                    node = norm_div(node, rhs)
            return node

        def parse_expr():
            node = parse_term()
            while peek() == '+' or peek() == '-':
                op = advance()[0]
                rhs = parse_term()
                if op == '+':
                    node = norm_add(node, rhs)
                else:
                    node = norm_sub(node, rhs)
            return node

        node = parse_expr()
        if pos != len(tokens):
            raise _Error

        p, q = node
        if q == 1:
            return str(p)
        return f"{p}/{q}"
    except Exception:
        return 'error'

