def schedule_jobs(jobs, workers):
    if workers < 1:
        return None
    if not jobs:
        return []

    records = []
    for j in jobs:
        records.append({
            'id': j[0],
            'release': j[1],
            'duration': j[2],
            'priority': j[3],
            'started': False,
        })

    idle = set(range(workers))
    running = []  # list of [end, worker]
    outputs = []
    t = 0

    while True:
        # Start jobs one at a time at time t
        while idle:
            best = None
            for rec in records:
                if rec['started'] or rec['release'] > t:
                    continue
                if best is None:
                    best = rec
                    continue
                if rec['priority'] != best['priority']:
                    if rec['priority'] > best['priority']:
                        best = rec
                    continue
                if rec['release'] != best['release']:
                    if rec['release'] < best['release']:
                        best = rec
                    continue
                if rec['id'] < best['id']:
                    best = rec
            if best is None:
                break
            worker = min(idle)
            idle.discard(worker)
            best['started'] = True
            end = t + best['duration']
            outputs.append([best['id'], worker, t, end])
            running.append([end, worker])

        # Advance to next event time
