def common_free_slots(calendars, day_start, day_end, min_len):
    try:
        if min_len < 1:
            return None
    except TypeError:
        return None

    def parse_time(s):
        if not isinstance(s, str):
            return None
        if s == '24:00':
            return 1440
        if len(s) != 5 or s[2] != ':':
            return None
        hh = s[:2]
        mm = s[3:]
        for c in hh + mm:
            if c < '0' or c > '9':
                return None
        h = int(hh)
        m = int(mm)
        if h > 23 or m > 59:
            return None
        return h * 60 + m

    ds = parse_time(day_start)
    de = parse_time(day_end)
    if ds is None or de is None:
        return None

    intervals = []
    for cal in calendars:
        offset, busy = cal
        for iv in busy:
            st, en = iv
            s = parse_time(st)
            e = parse_time(en)
            if s is None or e is None:
                return None
            if e <= s:
                continue
            us = s - offset
            ue = e - offset
            cs = max(us, ds)
            ce = min(ue, de)
            if ce > cs:
                intervals.append((cs, ce))

    if de <= ds:
        return []

    intervals.sort(key=lambda x: (x[0], x[1]))
    merged = []
    for s, e in intervals:
        if merged and s <= merged[-1][1]:
            if e > merged[-1][1]:
                merged[-1] = (merged[-1][0], e)
        else:
            merged.append((s, e))

    def fmt(m):
        if m == 1440:
            return '24:00'
        return '%02d:%02d' % (m // 60, m % 60)

    slots = []
    cursor = ds
    for s, e in merged:
        if s > cursor and s - cursor >= min_len:
            slots.append([fmt(cursor), fmt(s)])
        if e > cursor:
            cursor = e
    if de > cursor and de - cursor >= min_len:
        slots.append([fmt(cursor), fmt(de)])
    return slots

