    def parse_rule(rule):
        if not isinstance(rule, str):
            return None
        parts = rule.split(":")
        if len(parts) < 2:
            return None
        head = parts[0]
        if head == "day":
            if len(parts) != 2:
                return None
            s = parts[1]
            neg = False
            if s.startswith("-"):
                neg = True
                s = s[1:]
            if re.fullmatch(r"(?:[1-9]|1[0-9]|2[0-9]|3[01])", s) is None:
                return None
            return ("day", neg, int(s), None)
        if head == "nth":
            if len(parts) != 3:
                return None
            s = parts[1]
            neg = False
            if s.startswith("-"):
                neg = True
                s = s[1:]
            if re.fullmatch(r"[1-5]", s) is None:
                return None
            wd = parts[2]
            if wd not in _WEEKDAYS:
                return None
            return ("nth", neg, int(s), wd)
        return None

    if not isinstance(start, str):
        return None
    if re.fullmatch(r"[0-9]{4}-[0-9]{2}-[0-9]{2}", start) is None:
        return None
    try:
        start_date = date(int(start[:4]), int(start[5:7]), int(start[8:10]))
    except ValueError:
        return None

