import re
from datetime import date

def monthly_occurrences(start, rule, count):
    if not isinstance(start, str):
        return None
    m = re.fullmatch(r'([0-9]{4})-([0-9]{2})-([0-9]{2})', start)
    if m is None:
        return None
    try:
        start_date = date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
    except ValueError:
        return None

    if not isinstance(rule, str):
        return None
    if rule.startswith('day:'):
        rest = rule[4:]
        if rest.startswith('-'):
            sign = -1
            num_str = rest[1:]
        else:
            sign = 1
            num_str = rest
        if not re.fullmatch(r'[1-9][0-9]?', num_str):
            return None
        num = int(num_str)
        if num < 1 or num > 31:
            return None
        kind, wd = 'day', None
    elif rule.startswith('nth:'):
        parts = rule[4:].split(':')
        if len(parts) != 2:
            return None
        k_str, wd = parts
        if k_str.startswith('-'):
            sign = -1
            num_str = k_str[1:]
        else:
            sign = 1
            num_str = k_str
        if not re.fullmatch(r'[1-9]', num_str):
            return None
        num = int(num_str)
        if num < 1 or num > 5:
            return None
        if wd not in ('mon', 'tue', 'wed', 'thu', 'fri', 'sat', 'sun'):
            return None
        kind = 'nth'
    else:
        return None

    if count <= 0:
        return []

    wd_index = {'mon': 0, 'tue': 1, 'wed': 2, 'thu': 3, 'fri': 4, 'sat': 5, 'sun': 6}
    target = wd_index[wd] if wd is not None else None

    found = []
    year = start_date.year
    month = start_date.month
    while len(found) < count and year <= 9999:
        last = calendar.monthrange(year, month)[1]
        day = None
        if kind == 'day':
            if sign == 1:
                if num <= last:
                    day = num
            else:
                d = last - (num - 1)
                if d >= 1:
                    day = d
        else:
            days = [d for d in range(1, last + 1) if date(year, month, d).weekday() == target]
            if len(days) >= num:
                day = days[num - 1] if sign == 1 else days[-num]
        if day is not None:
            candidate = date(year, month, day)
            if candidate >= start_date:
                found.append(candidate.isoformat())
        month += 1
        if month == 13:
            month = 1
            year += 1
    return found

