        s = s[1:]
    elif s[0] == '+':
        return None
    if not s:
        return None
    if len(s) > 1 and s[0] == '0':
        return None
    for ch in s:
        if ch < '0' or ch > '9':
            return None
    return sign * int(s)


def _parse_rule(rule):
    parts = rule.split(':')
    kind = parts[0]
    if kind == 'day':
        if len(parts) != 2:
            return None
        n = _parse_number(parts[1])
        if n is None or n == 0 or abs(n) > 31:
            return None
        return ('day', n)
    if kind == 'nth':
        if len(parts) != 3:
            return None
        k = _parse_number(parts[1])
        if k is None or k == 0 or abs(k) > 5:
            return None
        if parts[2] not in _WEEKDAYS:
            return None
        return ('nth', k, _WEEKDAYS[parts[2]])
    return None


def _candidate_date(parsed, year, month):
    kind = parsed[0]
    value = parsed[1]
    _, last = calendar.monthrange(year, month)
    if kind == 'day':
        if value > 0:
            d = value
        else:
            d = last + value + 1
        if 1 <= d <= last:
            return date(year, month, d)
        return None
    weekday = parsed[2]
