        return None
    cnt = 0
    target = -value
    for d in range(last, 0, -1):
        if date(year, month, d).weekday() == weekday:
            cnt += 1
            if cnt == target:
                return date(year, month, d)
    return None


def monthly_occurrences(start, rule, count):
