        return None
    groups = (start[:4], start[5:7], start[8:])
    for group in groups:
        for ch in group:
            if ch < '0' or ch > '9':
                return None
    year = int(groups[0])
    month = int(groups[1])
    day = int(groups[2])
    try:
        first = date(year, month, day)
    except ValueError:
        return None

    parsed = _parse_rule(rule)
    if parsed is None:
        return None

    if count <= 0:
        return []

    results = []
    y, m = year, month
    while len(results) < count:
        if y > 9999 or (y == 9999 and m > 12):
