    def parse_literal(s):
        if s == '':
            return '#VALUE'
        i = 0
        if s[0] == '-':
            i = 1
        if i >= len(s):
            return '#VALUE'
        for ch in s[i:]:
            if not ('0' <= ch <= '9'):
                return '#VALUE'
        return int(s)

    def tokenize(text):
        tokens = []
        i = 0
        n = len(text)
        while i < n:
            ch = text[i]
            if ch.isspace():
                i += 1
                continue
            if ch in '+-*():':
                tokens.append(ch)
                i += 1
                continue
            if '0' <= ch <= '9':
                j = i
                while j < n and '0' <= text[j] <= '9':
                    j += 1
                tokens.append(('int', int(text[i:j])))
                i = j
                continue
            if ch == 'S' and text.startswith('SUM(', i):
                tokens.append('SUM(')
                i += 4
                continue
            if 'A' <= ch <= 'Z':
                j = i + 1
                k = j
                while k < n and '0' <= text[k] <= '9':
                    k += 1
                if k == j:
                    return None
                row = text[j:k]
                if not ((len(row) == 1 and '1' <= row[0] <= '9') or
                        (len(row) == 2 and '1' <= row[0] <= '9' and '0' <= row[1] <= '9')):
                    return None
                tokens.append(('ref', ch + row))
                i = k
                continue
            return None
        return tokens

    def parse_formula(text):
        tokens = tokenize(text)
        if tokens is None:
            return None
        pos = 0

        def peek():
            return tokens[pos] if pos < len(tokens) else None

        def advance():
            nonlocal pos
            t = tokens[pos]
            pos += 1
            return t

        def parse_expr():
            node = parse_term()
            if node is None:
                return None
            while peek() in ('+', '-'):
                op = advance()
                rhs = parse_term()
                if rhs is None:
