    def parse_literal(raw):
        if raw == '':
            return '#VALUE'
        if raw[0] == '-':
            digits = raw[1:]
            if digits and all('0' <= ch <= '9' for ch in digits):
                return -int(digits)
            return '#VALUE'
        if raw and all('0' <= ch <= '9' for ch in raw):
            return int(raw)
        return '#VALUE'

    def parse_ref_name(name):
        col = ord(name[0]) - ord('A')
        row = int(name[1:])
        return col, row

    def expand_refs(left, right):
        lcol, lrow = parse_ref_name(left)
        rcol, rrow = parse_ref_name(right)
        min_col = min(lcol, rcol)
        max_col = max(lcol, rcol)
        min_row = min(lrow, rrow)
        max_row = max(lrow, rrow)
        out = []
        for row in range(min_row, max_row + 1):
            for col in range(min_col, max_col + 1):
                out.append(chr(ord('A') + col) + str(row))
        return out

    def parse_formula(s):
        i = 0
        refs = []

        def peek():
            return s[i] if i < len(s) else ''

        def skip_spaces():
            nonlocal i
            while i < len(s) and s[i] == ' ':
                i += 1

        def parse_ref():
            nonlocal i
            skip_spaces()
            start = i
            if i >= len(s) or not ('A' <= s[i] <= 'Z'):
                raise SyntaxError('expected REF')
            i += 1
            if i >= len(s) or not ('0' <= s[i] <= '9'):
                raise SyntaxError('expected REF row')
            if s[i] == '0':
                raise SyntaxError('leading zero row')
            i += 1
            if i < len(s) and '0' <= s[i] <= '9':
                i += 1
            if i < len(s) and '0' <= s[i] <= '9':
                raise SyntaxError('row too long')
            return s[start:i]

        def parse_primary():
            nonlocal i
            skip_spaces()
            ch = peek()
            if ch == '(':
                i += 1
                node = parse_expr()
                skip_spaces()
                if peek() != ')':
                    raise SyntaxError('expected )')
                i += 1
                return node
            if ch == 'S' and s.startswith('SUM(', i):
                i += len('SUM(')
                left = parse_ref()
                skip_spaces()
