            for _ in range(neg):
                node = ('neg', node)
            return node

        def parse_term():
            nonlocal i
            node = parse_unary()
            while True:
                skip_spaces()
                if peek() == '*':
                    i += 1
                    right = parse_unary()
                    node = ('bin', '*', node, right)
                else:
                    return node

        def parse_expr():
            nonlocal i
            node = parse_term()
            while True:
                skip_spaces()
                if peek() == '+':
                    i += 1
                    right = parse_term()
                    node = ('bin', '+', node, right)
                elif peek() == '-':
                    i += 1
                    right = parse_term()
                    node = ('bin', '-', node, right)
                else:
                    return node

        node = parse_expr()
        skip_spaces()
        if i != len(s):
            raise SyntaxError('trailing tokens')
        return node, refs

    failed_formulas = set()
    parsed_ast = {}
    parsed_refs = {}
    for name, raw in cells.items():
        if not raw.startswith('='):
            continue
        try:
            node, refs = parse_formula(raw[1:])
            parsed_ast[name] = node
            parsed_refs[name] = refs
        except SyntaxError:
            failed_formulas.add(name)

    graph = {name: [r for r in refs if r in parsed_refs] for name, refs in parsed_refs.items()}
    cycle_set = set()
    for start in list(graph):
        if start in cycle_set:
            continue
        seen = set()
        stack = [start]
        found = False
        while stack and not found:
            node = stack.pop()
            if node in seen:
                continue
            seen.add(node)
            for nxt in graph[node]:
                if nxt == start:
                    found = True
                    break
                if nxt not in seen:
                    stack.append(nxt)
        if found:
            cycle_set.add(start)

    memo = {}

    def value_of(name):
        if name in memo:
            return memo[name]
        if name not in cells:
            memo[name] = 0
            return 0
        raw = cells[name]
        if not raw.startswith('='):
            v = parse_literal(raw)
            memo[name] = v
            return v
        if name in failed_formulas:
            memo[name] = '#SYNTAX'
            return '#SYNTAX'
        if name in cycle_set:
            memo[name] = '#CYCLE'
            return '#CYCLE'
        raise RuntimeError('unprocessed formula cell')

    def eval_node(root):
        stack = [(root, False)]
        values = []
        while stack:
            node, processed = stack.pop()
            if processed:
                if node[0] == 'int':
                    values.append(node[1])
                elif node[0] == 'ref':
                    values.append(value_of(node[1]))
                elif node[0] == 'sum':
                    total = 0
                    err = None
                    for r in node[3]:
                        v = value_of(r)
                        if isinstance(v, str):
                            err = v
                            break
                        total += v
                    if err is not None:
                        values.append(err)
                    else:
                        values.append(total)
                elif node[0] == 'neg':
                    v = values.pop()
                    if isinstance(v, str):
                        values.append(v)
                    else:
                        values.append(-v)
                elif node[0] == 'bin':
                    right = values.pop()
                    left = values.pop()
                    if isinstance(left, str):
                        values.append(left)
                    elif isinstance(right, str):
                        values.append(right)
                    else:
                        op = node[1]
                        if op == '+':
                            values.append(left + right)
                        elif op == '-':
                            values.append(left - right)
                        elif op == '*':
                            values.append(left * right)
                        else:
                            raise RuntimeError('bad operator')
                else:
                    raise RuntimeError('bad node')
                continue
            if node[0] in ('int', 'ref', 'sum'):
                stack.append((node, True))
            elif node[0] == 'neg':
                stack.append((node, True))
                stack.append((node[1], False))
            elif node[0] == 'bin':
                stack.append((node, True))
                stack.append((node[3], False))
                stack.append((node[2], False))
            else:
                raise RuntimeError('bad node')
        if values:
            return values.pop()
        return 0

    noncycle_nodes = [name for name in parsed_refs if name not in cycle_set]
    deps = {}
    for name in noncycle_nodes:
        dep_set = set()
        for r in parsed_refs[name]:
            if r in parsed_refs and r not in cycle_set:
                dep_set.add(r)
        deps[name] = dep_set
    dependents = {name: [] for name in noncycle_nodes}
    for name in noncycle_nodes:
        for dep in deps[name]:
            dependents[dep].append(name)
    remaining = {name: len(deps[name]) for name in noncycle_nodes}
    stack = [name for name in noncycle_nodes if remaining[name] == 0]
    while stack:
        name = stack.pop()
        refs = parsed_refs[name]
        err = None
        for r in refs:
            v = value_of(r)
            if isinstance(v, str):
                err = v
                break
        if err is not None:
            memo[name] = err
        else:
            memo[name] = eval_node(parsed_ast[name])
        for dependent in dependents[name]:
            remaining[dependent] -= 1
            if remaining[dependent] == 0:
                stack.append(dependent)

    results = {}
    for name in cells:
        results[name] = value_of(name)
    return results

def spreadsheet_eval(cells):
    def parse_literal(raw):
        s = raw
        i = 0
        if s.startswith('-'):
            i = 1
        if i >= len(s):
            return '#VALUE'
        for ch in s[i:]:
            if not ('0' <= ch <= '9'):
                return '#VALUE'
        return int(s)

    def tokenize(s):
        tokens = []
        i = 0
        n = len(s)
        while i < n:
            c = s[i]
            if c == ' ':
                i += 1
                continue
            if s.startswith('SUM(', i):
                tokens.append(('SUM(', 'SUM('))
                i += 4
                continue
            if c in '+-*:()':
                tokens.append((c, c))
                i += 1
                continue
            if '0' <= c <= '9':
                j = i
                while j < n and '0' <= s[j] <= '9':
                    j += 1
                tokens.append(('int', s[i:j]))
                i = j
                continue
            if 'A' <= c <= 'Z':
                k = i + 1
                while k < n and '0' <= s[k] <= '9':
                    k += 1
                tokens.append(('ref', s[i:k]))
                i = k
                continue
            return None
        return tokens

    def valid_ref(s):
        if len(s) < 2:
            return False
        letter = s[0]
        digits = s[1:]
        if not ('A' <= letter <= 'Z'):
            return False
        if not digits or not digits.isdigit():
            return False
        if digits[0] == '0':
            return False
        row = int(digits)
        return 1 <= row <= 99

    def parse_formula(s):
        tokens = tokenize(s)
        if tokens is None:
            return None
        pos = 0

        def peek():
            if pos < len(tokens):
                return tokens[pos]
            return None

        def advance():
            nonlocal pos
            t = tokens[pos]
            pos += 1
            return t

        def expect_ref():
            t = peek()
            if t is None or t[0] != 'ref':
                raise ValueError('expected ref')
            advance()
            if not valid_ref(t[1]):
                raise ValueError('invalid ref')
            return t[1]

        def parse_expr():
            node = parse_term()
            while peek() is not None and peek()[0] in ('+', '-'):
                op = advance()[0]
                rhs = parse_term()
                node = ('add' if op == '+' else 'sub', node, rhs)
            return node

        def parse_term():
            node = parse_unary()
            while peek() is not None and peek()[0] == '*':
                advance()
                rhs = parse_unary()
                node = ('mul', node, rhs)
            return node

        def parse_unary():
            if peek() is not None and peek()[0] == '-':
                advance()
                return ('neg', parse_unary())
            return parse_primary()

        def parse_primary():
            t = peek()
            if t is None:
                raise ValueError('unexpected end')
            if t[0] == 'int':
                advance()
                return ('num', int(t[1]))
            if t[0] == 'ref':
                advance()
                if not valid_ref(t[1]):
                    raise ValueError('invalid ref')
                return ('ref', t[1])
            if t[0] == 'SUM(':
                advance()
                r1 = expect_ref()
                if peek() is None or peek()[0] != ':':
                    raise ValueError('expected colon')
                advance()
                r2 = expect_ref()
                if peek() is None or peek()[0] != ')':
                    raise ValueError('expected )')
                advance()
                return ('sum', r1, r2)
            if t[0] == '(':
                advance()
                node = parse_expr()
                if peek() is None or peek()[0] != ')':
                    raise ValueError('expected )')
                advance()
                return node
            raise ValueError('unexpected token')

        try:
            node = parse_expr()
            if pos != len(tokens):
                raise ValueError('trailing tokens')
            return node
        except ValueError:
            return None

    def expand_refs(node):
        kind = node[0]
        if kind == 'num':
            return []
        if kind == 'ref':
            return [node[1]]
        if kind == 'sum':
            r1, r2 = node[1], node[2]
            c1 = ord(r1[0]) - 65
            c2 = ord(r2[0]) - 65
            row1 = int(r1[1:])
            row2 = int(r2[1:])
            out = []
            for row in range(min(row1, row2), max(row1, row2) + 1):
                for col in range(min(c1, c2), max(c1, c2) + 1):
                    out.append(chr(col + 65) + str(row))
            return out
        if kind == 'neg':
            return expand_refs(node[1])
        if kind in ('add', 'sub', 'mul'):
            return expand_refs(node[1]) + expand_refs(node[2])
        return []

    def eval_node(node, values):
        kind = node[0]
        if kind == 'num':
            return node[1]
        if kind == 'ref':
            return values[node[1]]
        if kind == 'sum':
            total = 0
            for r in expand_refs(node):
                total += values[r]
            return total
        if kind == 'neg':
            return -eval_node(node[1], values)
        if kind == 'add':
            return eval_node(node[1], values) + eval_node(node[2], values)
        if kind == 'sub':
            return eval_node(node[1], values) - eval_node(node[2], values)
        if kind == 'mul':
            return eval_node(node[1], values) * eval_node(node[2], values)
        return 0

    literal_value = {}
    ast = {}
    refs_map = {}
    for name, raw in cells.items():
        if raw.startswith('='):
            node = parse_formula(raw[1:])
            if node is None:
                ast[name] = None
                refs_map[name] = []
            else:
                ast[name] = node
                refs_map[name] = expand_refs(node)
        else:
            literal_value[name] = parse_literal(raw)

    def reaches_self(start):
        stack = list(refs_map.get(start, []))
        visited = set()
        while stack:
            node = stack.pop()
            if node == start:
                return True
            if node in visited:
                continue
            raw = cells.get(node)
            if raw is None:
                continue
            if not raw.startswith('='):
                continue
            visited.add(node)
            for r in refs_map.get(node, []):
                stack.append(r)
        return False

    cycle = set()
    for name, raw in cells.items():
        if not raw.startswith('='):
            continue
        if ast.get(name) is None:
            continue
        if reaches_self(name):
            cycle.add(name)

    values = {}

    def get_value(name):
        if name in values:
            return values[name]
        raw = cells.get(name)
        if raw is None:
            values[name] = 0
            return 0
        if not raw.startswith('='):
            v = literal_value[name]
            values[name] = v
            return v
        node = ast.get(name)
        if node is None:
            values[name] = '#SYNTAX'
            return '#SYNTAX'
        if name in cycle:
            values[name] = '#CYCLE'
            return '#CYCLE'
        for r in refs_map[name]:
            v = get_value(r)
            if not isinstance(v, int):
                values[name] = v
                return v
        val = eval_node(node, values)
        values[name] = val
        return val

    result = {}
    for name in cells:
        result[name] = get_value(name)
    return result

import re
import sys


def _tokenize(s):
    tokens = []
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c == ' ':
            i += 1
            continue
        if s.startswith('SUM(', i):
            tokens.append(('SUM', 'SUM('))
            i += 4
            continue
        if '0' <= c <= '9':
            j = i
            while j < n and '0' <= s[j] <= '9':
                j += 1
            tokens.append(('NUM', int(s[i:j])))
            i = j
            continue
        if 'A' <= c <= 'Z':
            j = i + 1
            k = j
            while k < n and '0' <= s[k] <= '9':
                k += 1
            row = s[j:k]
            if not row or row[0] == '0':
                return None
            if not (1 <= int(row) <= 99):
                return None
            tokens.append(('REF', c + row))
            i = k
            continue
        if c in '+-*():':
            tokens.append((c, c))
            i += 1
            continue
        return None
    return tokens


def _parse_formula(s):
    tokens = _tokenize(s)
    if not tokens:
        return None
    n = len(tokens)
    pos = 0

    def peek():
        if pos < n:
            return tokens[pos][0]
        return None

    def next_tok():
        nonlocal pos
        t = tokens[pos]
        pos += 1
        return t

    def parse_expr():
        node = parse_term()
        while peek() == '+' or peek() == '-':
            op = next_tok()[0]
            rhs = parse_term()
            node = (op, node, rhs)
        return node

    def parse_term():
        node = parse_unary()
        while peek() == '*':
            next_tok()
            rhs = parse_unary()
            node = ('*', node, rhs)
        return node

    def parse_unary():
        if peek() == '-':
            next_tok()
            return ('neg', parse_unary())
        return parse_primary()

    def parse_ref():
        if peek() != 'REF':
            raise SyntaxError
        return next_tok()[1]

    def parse_primary():
        p = peek()
        if p == 'NUM':
            return ('num', next_tok()[1])
        if p == 'REF':
            return ('ref', next_tok()[1])
        if p == 'SUM':
            next_tok()
            a = parse_ref()
            if peek() != ':':
                raise SyntaxError
            next_tok()
            b = parse_ref()
            if peek() != ')':
                raise SyntaxError
            next_tok()
            return ('sum', a, b)
        if p == '(':
            next_tok()
            node = parse_expr()
            if peek() != ')':
                raise SyntaxError
            next_tok()
            return node
        raise SyntaxError

    try:
        node = parse_expr()
        if pos != n:
            return None
        return node
    except Exception:
        return None


def _expand_range(a, b):
    col1 = ord(a[0])
    row1 = int(a[1:])
    col2 = ord(b[0])
    row2 = int(b[1:])
    out = []
    for r in range(min(row1, row2), max(row1, row2) + 1):
        for c in range(min(col1, col2), max(col1, col2) + 1):
            out.append(chr(c) + str(r))
    return out


def _collect_refs(node):
    tag = node[0]
    if tag == 'ref':
        return [node[1]]
    if tag == 'num':
        return []
    if tag == 'neg':
        return _collect_refs(node[1])
    if tag == 'sum':
        return _expand_range(node[1], node[2])
    return _collect_refs(node[1]) + _collect_refs(node[2])


def _eval_ast(node, get_value):
    tag = node[0]
    if tag == 'num':
        return node[1]
    if tag == 'ref':
        return get_value(node[1])
    if tag == 'neg':
        return -_eval_ast(node[1], get_value)
    if tag == 'sum':
        total = 0
        for cell in _expand_range(node[1], node[2]):
            total += get_value(cell)
        return total
    left = _eval_ast(node[1], get_value)
    right = _eval_ast(node[2], get_value)
    if tag == '+':
        return left + right
    if tag == '-':
        return left - right
    return left * right


def spreadsheet_eval(cells):
    sys.setrecursionlimit(max(sys.getrecursionlimit(), 100000))
    is_formula = {}
    ast = {}
    refs = {}
    literal_value = {}

    for key, raw in cells.items():
        if raw.startswith('='):
            is_formula[key] = True
            node = _parse_formula(raw[1:])
            ast[key] = node
            refs[key] = _collect_refs(node) if node is not None else []
        else:
            is_formula[key] = False
            if re.fullmatch(r'-?[0-9]+', raw):
                literal_value[key] = int(raw)
            else:
                literal_value[key] = '#VALUE'
            refs[key] = []

    def can_reach_self(k):
        stack = list(refs[k])
        seen = set()
        while stack:
            cur = stack.pop()
            if cur == k:
                return True
            if cur in seen:
                continue
            seen.add(cur)
            for r in refs.get(cur, []):
                if r not in seen:
                    stack.append(r)
        return False

    in_cycle = set()
    for key in cells:
        if is_formula[key] and ast[key] is not None:
            if can_reach_self(key):
                in_cycle.add(key)

    values = {}

    def get_value(cell):
        if cell in values:
            return values[cell]
        if cell not in cells:
            return 0
        if not is_formula[cell]:
            v = literal_value[cell]
            values[cell] = v
            return v
        if ast[cell] is None:
            v = '#SYNTAX'
            values[cell] = v
            return v
        if cell in in_cycle:
            v = '#CYCLE'
            values[cell] = v
            return v
        for r in refs[cell]:
            v = get_value(r)
            if isinstance(v, str):
                values[cell] = v
                return v
        v = _eval_ast(ast[cell], get_value)
        values[cell] = v
        return v

    result = {}
    for key in cells:
        result[key] = get_value(key)
    return result

