        col2 = ord(r2[0]); row2 = int(r2[1:])
        c1 = col1 if col1 < col2 else col2
        c2 = col2 if col1 < col2 else col1
        rl = row1 if row1 < row2 else row2
        rh = row2 if row1 < row2 else row1
        out = []
        for r in range(rl, rh + 1):
            for c in range(c1, c2 + 1):
                out.append(chr(c) + str(r))
        return out

    class ParseError(Exception):
        pass

    def tokenize(expr):
        tokens = []
        i = 0
        n = len(expr)
        while i < n:
            c = expr[i]
            if c == ' ':
                i += 1
                continue
            if '0' <= c <= '9':
                j = i
                while j < n and '0' <= expr[j] <= '9':
                    j += 1
                tokens.append(('num', int(expr[i:j])))
                i = j
                continue
            if c == 'S' and expr.startswith('SUM(', i):
                tokens.append(('sum',))
                i += 4
                continue
            if 'A' <= c <= 'Z':
                j = i + 1
                while j < n and '0' <= expr[j] <= '9':
                    j += 1
                row_str = expr[i + 1:j]
                if not row_str:
                    raise ParseError('REF missing row')
                if row_str[0] == '0':
                    raise ParseError('REF leading zero')
                row = int(row_str)
                if row < 1 or row > 99:
                    raise ParseError('REF out of range')
                tokens.append(('ref', c + row_str))
                i = j
                continue
            if c == '(':
                tokens.append(('lparen',)); i += 1; continue
            if c == ')':
                tokens.append(('rparen',)); i += 1; continue
            if c == ':':
                tokens.append(('colon',)); i += 1; continue
            if c == '+':
                tokens.append(('plus',)); i += 1; continue
            if c == '-':
                tokens.append(('minus',)); i += 1; continue
            if c == '*':
                tokens.append(('star',)); i += 1; continue
            raise ParseError('bad char')
        return tokens

    def parse_formula(expr):
        tokens = tokenize(expr)
        refs = []
        pos = 0

        def peek():
            if pos < len(tokens):
                return tokens[pos]
            return None

        def advance():
            nonlocal pos
            tok = tokens[pos]
            pos += 1
            return tok

        def parse_expr():
            left = parse_term()
            while True:
                tok = peek()
                if tok is not None and tok[0] in ('plus', 'minus'):
                    advance()
                    right = parse_term()
                    left = ('add' if tok[0] == 'plus' else 'sub', left, right)
                else:
                    return left

        def parse_term():
            left = parse_unary()
