                tok = peek()
                if tok is not None and tok[0] == 'star':
                    advance()
                    right = parse_unary()
                    left = ('mul', left, right)
                else:
                    return left

        def parse_unary():
            tok = peek()
            if tok is not None and tok[0] == 'minus':
                advance()
