                advance()
                return ('num', tok[1])
            if tok[0] == 'ref':
                advance()
                refs.append(tok[1])
                return ('ref', tok[1])
            if tok[0] == 'sum':
                advance()
                t = peek()
                if t is None or t[0] != 'ref':
                    raise ParseError('expected REF')
                advance()
                r1 = t[1]
                t = peek()
                if t is None or t[0] != 'colon':
                    raise ParseError('expected colon')
                advance()
                t = peek()
                if t is None or t[0] != 'ref':
                    raise ParseError('expected REF')
                advance()
                r2 = t[1]
                t = peek()
                if t is None or t[0] != 'rparen':
                    raise ParseError('expected )')
