        kind = node[0]
        if kind == 'num':
            return node[1]
        if kind == 'ref':
            return value_of(node[1])
        if kind == 'sum':
            total = 0
            for r in expand_refs(node[1], node[2]):
                total += value_of(r)
            return total
        if kind == 'add':
            return eval_ast(node[1], value_of) + eval_ast(node[2], value_of)
        if kind == 'sub':
            return eval_ast(node[1], value_of) - eval_ast(node[2], value_of)
        if kind == 'mul':
            return eval_ast(node[1], value_of) * eval_ast(node[2], value_of)
        if kind == 'neg':
            return -eval_ast(node[1], value_of)
        raise ParseError('bad ast')

    info = {}
    for name, raw in cells.items():
        if not raw.startswith('='):
            i = 0
            if raw.startswith('-'):
                i = 1
            ok = i < len(raw)
            if ok:
                for j in range(i, len(raw)):
                    if raw[j] < '0' or raw[j] > '9':
                        ok = False
