            if ok:
                info[name] = ('lit', int(raw))
            else:
                info[name] = ('err', '#VALUE')
            continue
        try:
            ast, refs = parse_formula(raw[1:])
        except Exception:
            info[name] = ('err', '#SYNTAX')
        else:
            info[name] = ('formula', ast, refs)

    cycle_set = set()
    for name, rec in info.items():
        if rec[0] != 'formula':
            continue
        refs = rec[2]
        stack = list(refs)
        visited = set()
        found = False
        while stack:
            r = stack.pop()
            if r == name:
                found = True
                break
            if r in visited:
                continue
            visited.add(r)
            rec2 = info.get(r)
            if rec2 is not None and rec2[0] == 'formula':
                stack.extend(rec2[2])
        if found:
            cycle_set.add(name)

    memo = {}
    def value_of(name):
        if name in memo:
            return memo[name]
        rec = info.get(name)
        if rec is None:
            memo[name] = 0
            return 0
        if rec[0] == 'lit':
            memo[name] = rec[1]
            return rec[1]
        if rec[0] == 'err':
