            return '#CYCLE'
        ast, refs = rec[1], rec[2]
        for r in refs:
            v = value_of(r)
            if isinstance(v, str):
                memo[name] = v
                return v
        v = eval_ast(ast, value_of)
        memo[name] = v
        return v

    result = {}
    for name in cells:
        result[name] = value_of(name)
    return result

