def spreadsheet_eval(cells):
    REF_RE = re.compile(r'[A-Z][1-9][0-9]?')

    def tokenize(s):
        tokens = []
        i = 0
        n = len(s)
        while i < n:
            c = s[i]
            if c == ' ':
                i += 1
                continue
            if '0' <= c <= '9':
                j = i
                while j < n and '0' <= s[j] <= '9':
                    j += 1
                tokens.append(('num', int(s[i:j])))
                i = j
                continue
            if c in '+-*:()':
                tokens.append((c, c))
                i += 1
                continue
            if c == 'S' and s.startswith('SUM(', i):
                tokens.append(('SUM(',))
                i += 4
                continue
            if 'A' <= c <= 'Z':
                m = REF_RE.match(s, i)
                if m:
                    tokens.append(('ref', m.group()))
                    i = m.end()
                    continue
                raise SyntaxError('bad REF')
            raise SyntaxError('bad char')
        return tokens

    def parse(tokens):
        pos = 0

        def parse_ref_token():
            nonlocal pos
            if pos >= len(tokens) or tokens[pos][0] != 'ref':
                raise SyntaxError('expected REF')
            name = tokens[pos][1]
            pos += 1
            return name

        def parse_primary():
            nonlocal pos
            if pos >= len(tokens):
                raise SyntaxError('unexpected end')
            tok = tokens[pos]
            if tok[0] == 'SUM(':
                pos += 1
                a = parse_ref_token()
                if pos >= len(tokens) or tokens[pos][0] != ':':
                    raise SyntaxError('expected :')
                pos += 1
                b = parse_ref_token()
                if pos >= len(tokens) or tokens[pos][0] != ')':
                    raise SyntaxError('expected )')
