                return ('sum', a, b)
            if tok[0] == '(':
                pos += 1
                node = parse_expr()
                if pos >= len(tokens) or tokens[pos][0] != ')':
                    raise SyntaxError('expected )')
                pos += 1
                return node
            if tok[0] == 'num':
                pos += 1
                return ('num', tok[1])
            if tok[0] == 'ref':
                pos += 1
                return ('ref', tok[1])
            raise SyntaxError('bad primary')

        def parse_unary():
            nonlocal pos
            if pos < len(tokens) and tokens[pos][0] == '-':
                pos += 1
                return ('neg', parse_unary())
            return parse_primary()

        def parse_term():
            nonlocal pos
            node = parse_unary()
            while pos < len(tokens) and tokens[pos][0] == '*':
                pos += 1
                rhs = parse_unary()
                node = ('bin', '*', node, rhs)
            return node

        def parse_expr():
            nonlocal pos
            node = parse_term()
            while pos < len(tokens) and tokens[pos][0] in ('+', '-'):
                op = tokens[pos][0]
                pos += 1
                rhs = parse_term()
                node = ('bin', op, node, rhs)
            return node

        node = parse_expr()
        if pos != len(tokens):
            raise SyntaxError('trailing tokens')
        return node

