                i += 1
                continue
            if '0' <= ch <= '9':
                j = i + 1
                while j < n and '0' <= expr[j] <= '9':
                    j += 1
                tokens.append(expr[i:j])
                i = j
                continue
            if ch in '+-*/^()':
                tokens.append(ch)
                i += 1
                continue
            return 'error'

        pos = 0

