            return tokens[pos] if pos < len(tokens) else None

        def advance():
            nonlocal pos
            tok = tokens[pos]
            pos += 1
            return tok

        def parse_expr():
            value = parse_term()
            while peek() == '+' or peek() == '-':
                op = advance()
                rhs = parse_term()
                if op == '+':
                    value = value + rhs
                else:
