            j += 1
        return path[i:j], j

    def recurse(v, name):
        out = []
        stack = [v]
        while stack:
            node = stack.pop()
            if isinstance(node, dict):
                if name in node:
                    out.append(node[name])
                children = list(node.values())
                for val in reversed(children):
                    stack.append(val)
            elif isinstance(node, list):
                for val in reversed(node):
                    stack.append(val)
        return out

    steps = []
    i = 1
    while i < n:
        c = path[i]
        if c == '.':
            if i + 1 < n and path[i + 1] == '.':
                m = parse_name(i + 2)
                if m is None:
                    return None
                name, i = m
                steps.append(('recurse', name))
            else:
                m = parse_name(i + 1)
                if m is None:
                    return None
                name, i = m
                steps.append(('key', name))
        elif c == '[':
            j = i + 1
            if j >= n:
                return None
            ch = path[j]
            if ch == '*':
                j += 1
                if j >= n or path[j] != ']':
                    return None
                j += 1
                steps.append(('all',))
                i = j
            elif ch == '\'':
                j += 1
                text = []
                while True:
                    if j >= n:
                        return None
                    ch = path[j]
                    if ch == '\\':
                        if j + 1 >= n:
                            return None
                        nxt = path[j + 1]
                        if nxt == '\'':
                            text.append('\'')
                            j += 2
                        elif nxt == '\\':
                            text.append('\\')
                            j += 2
                        else:
                            return None
                    elif ch == '\'':
                        j += 1
                        break
                    else:
                        text.append(ch)
                        j += 1
                if j >= n or path[j] != ']':
                    return None
                j += 1
                steps.append(('key', ''.join(text)))
                i = j
            else:
                minus = False
                if ch == '-':
                    minus = True
                    j += 1
                if j >= n or not ('0' <= path[j] <= '9'):
                    return None
                dstart = j
                while j < n and '0' <= path[j] <= '9':
                    j += 1
                digits = path[dstart:j]
                if len(digits) > 1 and digits[0] == '0':
                    return None
                if j >= n or path[j] != ']':
                    return None
                j += 1
                val = int(digits)
                if minus:
                    val = -val
                steps.append(('index', val))
                i = j
        else:
            return None

    current = [doc]
    for step in steps:
        typ = step[0]
        new_current = []
        if typ == 'key':
            name = step[1]
            for v in current:
                if isinstance(v, dict) and name in v:
                    new_current.append(v[name])
        elif typ == 'index':
            idx = step[1]
            for v in current:
                if isinstance(v, list):
                    if idx < 0:
                        pos = len(v) + idx
                    else:
                        pos = idx
                    if 0 <= pos < len(v):
                        new_current.append(v[pos])
        elif typ == 'all':
            for v in current:
                if isinstance(v, list):
                    new_current.extend(v)
                elif isinstance(v, dict):
                    for val in v.values():
                        new_current.append(val)
        else:
            name = step[1]
            for v in current:
                new_current.extend(recurse(v, name))
        current = new_current
    return current

def json_select(doc, path):
    if not isinstance(path, str):
        return None
    if not path.startswith('$'):
        return None

    def is_name_start(c):
        return ('a' <= c <= 'z') or ('A' <= c <= 'Z') or c == '_'

    def is_name_char(c):
        return ('a' <= c <= 'z') or ('A' <= c <= 'Z') or ('0' <= c <= '9') or c == '_'

    steps = []
    i = 1
    n = len(path)

    while i < n:
        c = path[i]
        if c == '.':
            if i + 1 >= n:
                return None
            if path[i + 1] == '.':
                j = i + 2
                if j >= n or not is_name_start(path[j]):
                    return None
                k = j + 1
                while k < n and is_name_char(path[k]):
                    k += 1
                steps.append(('recurse', path[j:k]))
                i = k
            else:
                j = i + 1
                if not is_name_start(path[j]):
                    return None
                k = j + 1
                while k < n and is_name_char(path[k]):
                    k += 1
                steps.append(('key', path[j:k]))
                i = k
        elif c == '[':
            if i + 1 >= n:
                return None
            nxt = path[i + 1]
            if nxt == "'":
                j = i + 2
                chars = []
                closed = False
                while j < n:
                    ch = path[j]
                    if ch == '\\':
                        if j + 1 >= n:
                            return None
                        esc = path[j + 1]
                        if esc == '\\':
                            chars.append('\\')
                            j += 2
                        elif esc == "'":
                            chars.append("'")
                            j += 2
                        else:
                            return None
                    elif ch == "'":
                        if j + 1 >= n or path[j + 1] != ']':
                            return None
                        steps.append(('key', ''.join(chars)))
                        i = j + 2
                        closed = True
                        break
                    else:
                        chars.append(ch)
                        j += 1
                if not closed:
                    return None
            elif nxt == '*':
                if i + 2 >= n or path[i + 2] != ']':
                    return None
                steps.append(('star',))
                i = i + 3
            else:
                j = i + 1
                sign = 1
                if path[j] == '-':
                    sign = -1
                    j += 1
                start = j
                while j < n and '0' <= path[j] <= '9':
                    j += 1
                digits = path[start:j]
                if not digits:
                    return None
                if digits != '0' and digits.startswith('0'):
                    return None
                if j >= n or path[j] != ']':
                    return None
                steps.append(('index', sign * int(digits)))
                i = j + 1
        else:
            return None

    current = [doc]
    for step in steps:
        kind = step[0]
        new = []
        if kind == 'key':
            key = step[1]
            for v in current:
                if isinstance(v, dict) and key in v:
                    new.append(v[key])
        elif kind == 'index':
            idx = step[1]
            for v in current:
                if isinstance(v, list):
                    ln = len(v)
                    if idx >= 0:
                        if idx < ln:
                            new.append(v[idx])
                    else:
                        pos = ln + idx
                        if 0 <= pos < ln:
                            new.append(v[pos])
        elif kind == 'star':
            for v in current:
                if isinstance(v, list):
                    new.extend(v)
                elif isinstance(v, dict):
                    new.extend(v.values())
        else:
            key = step[1]
            for v in current:
                stack = [v]
                while stack:
                    node = stack.pop()
                    if isinstance(node, dict):
                        if key in node:
                            new.append(node[key])
                        for val in reversed(list(node.values())):
                            if isinstance(val, (list, dict)):
                                stack.append(val)
                    elif isinstance(node, list):
                        for val in reversed(node):
                            if isinstance(val, (list, dict)):
                                stack.append(val)
        current = new
    return current

def _parse_name(path, i):
    n = len(path)
    if i >= n:
        return None, i
    c = path[i]
    if not ('A' <= c <= 'Z' or 'a' <= c <= 'z' or c == '_'):
        return None, i
    j = i + 1
    while j < n:
        ch = path[j]
        if ('A' <= ch <= 'Z' or 'a' <= ch <= 'z' or '0' <= ch <= '9' or ch == '_'):
            j += 1
        else:
            break
    return path[i:j], j


def _parse_bracket(path, i):
    n = len(path)
    j = i + 1
    if j >= n:
        return None
    c = path[j]
    if c == '*':
        if j + 1 < n and path[j + 1] == ']':
            return ('star',), j + 2
        return None
    if c == "'":
        text = []
        k = j + 1
        while True:
            if k >= n:
                return None
            ch = path[k]
            if ch == '\\':
                if k + 1 >= n:
                    return None
                nxt = path[k + 1]
                if nxt == "'":
                    text.append("'")
                    k += 2
                elif nxt == '\\':
                    text.append('\\')
                    k += 2
                else:
                    return None
            elif ch == "'":
                if k + 1 >= n or path[k + 1] != ']':
                    return None
                return ('key', ''.join(text)), k + 2
            else:
                text.append(ch)
                k += 1
    k = j
    minus = False
    if path[k] == '-':
        minus = True
        k += 1
    start = k
    while k < n and '0' <= path[k] <= '9':
        k += 1
    digits = path[start:k]
    if not digits:
        return None
    if digits != '0' and digits.startswith('0'):
        return None
    if k >= n or path[k] != ']':
        return None
    num = int(('-' if minus else '') + digits)
    return ('index', num), k + 1


def _parse_path(path):
    if not isinstance(path, str):
        return None
    if not path.startswith('$'):
        return None
    steps = []
    i = 1
    n = len(path)
    while i < n:
        c = path[i]
        if c == '.':
            if i + 1 < n and path[i + 1] == '.':
                name, j = _parse_name(path, i + 2)
                if name is None:
                    return None
                steps.append(('rec', name))
                i = j
            else:
                name, j = _parse_name(path, i + 1)
                if name is None:
                    return None
                steps.append(('key', name))
                i = j
        elif c == '[':
            parsed = _parse_bracket(path, i)
            if parsed is None:
                return None
            step, j = parsed
            steps.append(step)
            i = j
        else:
            return None
    return steps


def json_select(doc, path):
    steps = _parse_path(path)
    if steps is None:
        return None
    current = [doc]
    for step in steps:
        kind = step[0]
        next_current = []
        if kind == 'key':
            key = step[1]
            for value in current:
                if isinstance(value, dict) and key in value:
                    next_current.append(value[key])
        elif kind == 'index':
            num = step[1]
            for value in current:
                if isinstance(value, list):
                    idx = num if num >= 0 else len(value) + num
                    if 0 <= idx < len(value):
                        next_current.append(value[idx])
        elif kind == 'star':
            for value in current:
                if isinstance(value, list):
                    next_current.extend(value)
                elif isinstance(value, dict):
                    next_current.extend(value.values())
        elif kind == 'rec':
            name = step[1]
            for value in current:
                out = []
                stack = [value]
                while stack:
                    node = stack.pop()
                    if isinstance(node, dict):
                        if name in node:
                            out.append(node[name])
                        for v in reversed(list(node.values())):
                            stack.append(v)
                    elif isinstance(node, list):
                        for v in reversed(node):
                            stack.append(v)
                next_current.extend(out)
        current = next_current
    return current

def decode_repeat(text):
    LIMIT = 10000
    CAP = LIMIT + 1

    def capped_count(run):
        stripped = run.lstrip('0')
        if not stripped:
            return 0
        if len(stripped) >= 6:
            return CAP
        if len(stripped) == 5:
            if stripped == '10000':
                return 10000
            return CAP
        return int(stripped)

    n = len(text)

    # Pass 1: validate and compute the capped decoded length.
    stack = [[1, 0]]  # [count, capped content length]; dummy top-level frame
    i = 0
    while i < n:
        c = text[i]
        if c == '\\':
            if i + 1 >= n:
                return None
            frame = stack[-1]
            v = frame[1] + 1
            frame[1] = v if v <= CAP else CAP
            i += 2
            continue
        if '0' <= c <= '9':
            j = i
            while j < n and '0' <= text[j] <= '9':
                j += 1
            run = text[i:j]
            if j < n and text[j] == '[':
                stack.append([capped_count(run), 0])
                i = j + 1
            else:
                frame = stack[-1]
                v = frame[1] + (j - i)
                frame[1] = v if v <= CAP else CAP
                i = j
            continue
        if c == '[':
            return None
        if c == ']':
            if len(stack) == 1:
                return None
            frame = stack.pop()
            count = frame[0]
            content_len = frame[1]
            if count == 0 or content_len == 0:
                contribution = 0
            elif content_len >= CAP or count >= CAP:
                contribution = CAP
            else:
                val = content_len * count
                contribution = val if val <= LIMIT else CAP
            parent = stack[-1]
            v = parent[1] + contribution
            parent[1] = v if v <= CAP else CAP
            i += 1
            continue
        frame = stack[-1]
        v = frame[1] + 1
        frame[1] = v if v <= CAP else CAP
        i += 1

    if len(stack) > 1:
        return None
    final_len = stack[0][1]
    if final_len > LIMIT:
        return None

    # Pass 2: build the exact string (final_len <= LIMIT).
    stack2 = [[1, []]]
    i = 0
    while i < n:
        c = text[i]
        if c == '\\':
            stack2[-1][1].append(text[i + 1])
            i += 2
            continue
        if '0' <= c <= '9':
            j = i
            while j < n and '0' <= text[j] <= '9':
                j += 1
            run = text[i:j]
            if j < n and text[j] == '[':
                count = capped_count(run)
                if count == 0:
                    # Skip the content without building it; expansion is ''.
                    k = j + 1
                    depth = 1
                    while k < n and depth > 0:
                        ck = text[k]
                        if ck == '\\':
                            k += 2
                            continue
                        if ck == '[':
                            depth += 1
                        elif ck == ']':
                            depth -= 1
                        k += 1
                    i = k
                    continue
                stack2.append([count, []])
                i = j + 1
            else:
                stack2[-1][1].append(run)
                i = j
            continue
        if c == '[':
            return None  # unreachable (validated)
        if c == ']':
            frame = stack2.pop()
            count = frame[0]
            parts = frame[1]
            if not parts:
                expanded = ''
            elif count > LIMIT:
                return None  # unreachable (limit already checked)
            else:
                expanded = ''.join(parts) * count
            stack2[-1][1].append(expanded)
            i += 1
            continue
        stack2[-1][1].append(c)
        i += 1

    return ''.join(stack2[0][1])

def decode_repeat(text):
