            else:
                decoded = content_str * count
            if decoded is TOO_BIG:
                parent_too_big = True
            else:
                if not parent_too_big:
                    parent_parts.append(decoded)
                    parent_length += len(decoded)
                    if parent_length > LIMIT:
                        parent_length = LIMIT
                        parent_too_big = True
            cur_parts = parent_parts
            cur_length = parent_length
            cur_too_big = parent_too_big
            i += 1
            continue
        if not cur_too_big and cur_length < LIMIT:
            cur_parts.append(c)
            cur_length += 1
        else:
            cur_too_big = True
        i += 1
    if frames:
        return None
    if cur_too_big:
        return None
    result = ''.join(cur_parts)
    if len(result) > LIMIT:
        return None
    return result

def decode_repeat(text):
    if not isinstance(text, str):
        return None
    LIMIT = 10000
    CAP = LIMIT + 1
    n = len(text)
    stack = [{'nodes': [], 'count': None}]
    lit_buf = []

    def flush_lit():
        if lit_buf:
            stack[-1]['nodes'].append(('lit', ''.join(lit_buf)))
            lit_buf.clear()

    i = 0
    while i < n:
        c = text[i]
        if c == '\\':
            if i + 1 >= n:
                return None
            flush_lit()
            stack[-1]['nodes'].append(('lit', text[i + 1]))
            i += 2
            continue
        if '0' <= c <= '9':
            j = i
            while j < n and '0' <= text[j] <= '9':
                j += 1
            run = text[i:j]
            if j < n and text[j] == '[':
                flush_lit()
                stripped = run.lstrip('0')
                if not stripped:
                    count = 0
                elif len(stripped) > 5:
                    count = CAP  # definitely larger than the limit
                else:
                    try:
                        count = int(stripped)
                    except ValueError:
                        count = CAP
                stack.append({'nodes': [], 'count': count})
                i = j + 1
                continue
            lit_buf.append(run)
            i = j
            continue
        if c == '[':
            return None
        if c == ']':
            if len(stack) == 1:
                return None
            flush_lit()
            frame = stack.pop()
            content_nodes = frame['nodes']
            content_len = 0
            for nd in content_nodes:
                if nd[0] == 'lit':
                    content_len += len(nd[1])
                else:
                    content_len += nd[3]
                if content_len > CAP:
                    content_len = CAP
                    break
            rep_len = frame['count'] * content_len
            if rep_len > CAP:
                rep_len = CAP
            stack[-1]['nodes'].append(('rep', frame['count'], content_nodes, rep_len))
            i += 1
            continue
        lit_buf.append(c)
        i += 1

    flush_lit()
    if len(stack) != 1:
        return None

    total = 0
    for nd in stack[0]['nodes']:
        if nd[0] == 'lit':
            total += len(nd[1])
        else:
            total += nd[3]
        if total > CAP:
            total = CAP
            break
    if total > LIMIT:
        return None

    nodes = stack[0]['nodes']
    root_parts = []
    build_stack = [[nodes, 0, root_parts, None, None]]
    while build_stack:
        frame = build_stack[-1]
        nodes_f, idx, parts, parent_parts, count = frame
        if idx < len(nodes_f):
            node = nodes_f[idx]
            frame[1] = idx + 1
            if node[0] == 'lit':
                parts.append(node[1])
            else:
                c = node[1]
                if c != 0:
                    build_stack.append([node[2], 0, [], parts, c])
            continue
        build_stack.pop()
        content_str = ''.join(parts)
        if parent_parts is not None:
            parent_parts.append(content_str * count)
        else:
            return content_str
    return ''.join(root_parts)

def decode_repeat(text):
    LIMIT = 10000
    n = len(text)

    def is_digit(c):
        return '0' <= c <= '9'

    def is_zero_count(digits):
        return not any(ch != '0' for ch in digits)

    def count_gt(digits, threshold):
        s = digits.lstrip('0')
        if not s:
            return False
        st = str(threshold)
        if len(s) != len(st):
            return len(s) > len(st)
        return s > st

    stack = []
    total = 0

    def bump_len(k):
        nonlocal total
        if stack:
            stack[-1][1] = min(LIMIT + 1, stack[-1][1] + k)
        else:
            total = min(LIMIT + 1, total + k)

    i = 0
    invalid = False
    while i < n:
        c = text[i]
        if c == '\\':
            if i + 1 >= n:
                invalid = True
                break
            bump_len(1)
            i += 2
            continue
        if is_digit(c):
            j = i + 1
            while j < n and is_digit(text[j]):
                j += 1
            if j < n and text[j] == '[':
                stack.append([text[i:j], 0])
                i = j + 1
            else:
                bump_len(j - i)
                i = j
            continue
        if c == '[':
            invalid = True
            break
        if c == ']':
            if not stack:
                invalid = True
                break
            digits, content_len = stack.pop()
            if content_len == 0 or is_zero_count(digits):
                contrib = 0
            else:
                threshold = (LIMIT + 1) // content_len
                if count_gt(digits, threshold):
                    contrib = LIMIT + 1
                else:
                    contrib = int(digits) * content_len
            if stack:
                stack[-1][1] = min(LIMIT + 1, stack[-1][1] + contrib)
            else:
                total = min(LIMIT + 1, total + contrib)
            i += 1
            continue
        bump_len(1)
        i += 1

    if invalid or stack:
        return None
    if total > LIMIT:
        return None

    parts = []
    stack_parts = []
    stack_counts = []

    def current_parts():
        return stack_parts[-1] if stack_parts else parts

    def skip_block(pos):
        depth = 1
        k = pos
        while depth:
            if k >= n:
                return None
            ch = text[k]
            if ch == '\\':
                if k + 1 >= n:
                    return None
                k += 2
                continue
            if ch == '[':
                depth += 1
                k += 1
            elif ch == ']':
                depth -= 1
                k += 1
            else:
                k += 1
        return k

    i = 0
    while i < n:
        c = text[i]
        if c == '\\':
            if i + 1 >= n:
                return None
            current_parts().append(text[i + 1])
            i += 2
            continue
        if is_digit(c):
            j = i + 1
            while j < n and is_digit(text[j]):
                j += 1
            if j < n and text[j] == '[':
                digits = text[i:j]
                if is_zero_count(digits):
                    pos = skip_block(j + 1)
                    if pos is None:
                        return None
                    i = pos
                    continue
                stack_parts.append([])
                stack_counts.append(digits)
                i = j + 1
            else:
                current_parts().append(text[i:j])
                i = j
            continue
        if c == '[':
            return None
        if c == ']':
            if not stack_parts:
                return None
            digits = stack_counts.pop()
            s = ''.join(stack_parts.pop())
            if s:
                current_parts().append(s * int(digits))
            i += 1
            continue
        current_parts().append(c)
        i += 1

    if stack_parts or stack_counts:
        return None
    return ''.join(parts)

def decode_repeat(text):
    LIMIT = 10000

    def cap(x):
        return x if x <= LIMIT else LIMIT + 1

    def count_of(s):
        s = s.lstrip('0')
        if not s:
            return 0
        if len(s) > 20:
            return None
        return int(s)

    class Invalid(Exception):
        pass

    n = len(text)

    # validation pass (computes capped length without building strings)
    stack = [{'len': 0, 'count': None}]
    i = 0
    try:
        while i < n:
            c = text[i]
            if c == '\\':
                if i + 1 >= n:
                    raise Invalid()
                top = stack[-1]
                top['len'] = cap(top['len'] + 1)
                i += 2
                continue
            if '0' <= c <= '9':
                j = i + 1
                while j < n and '0' <= text[j] <= '9':
                    j += 1
                if j < n and text[j] == '[':
                    count = count_of(text[i:j])
                    stack.append({'len': 0, 'count': count})
                    i = j + 1
                    continue
                top = stack[-1]
                top['len'] = cap(top['len'] + (j - i))
                i = j
                continue
            if c == '[':
                raise Invalid()
            if c == ']':
                if len(stack) == 1:
                    raise Invalid()
                frame = stack.pop()
                flen = frame['len']
                count = frame['count']
                if flen == 0 or count == 0:
                    contribution = 0
                elif count is None or flen > LIMIT:
                    contribution = LIMIT + 1
                else:
                    threshold = LIMIT // flen
                    contribution = LIMIT + 1 if count > threshold else count * flen
                parent = stack[-1]
                parent['len'] = cap(parent['len'] + contribution)
                i += 1
                continue
            top = stack[-1]
            top['len'] = cap(top['len'] + 1)
            i += 1
        if len(stack) != 1:
            raise Invalid()
    except Invalid:
        return None

    total = stack[0]['len']
    if total > LIMIT:
        return None

    # build pass (only runs when the final result fits)
    stack = [{'parts': [], 'count': None}]
    i = 0
    try:
        while i < n:
            c = text[i]
            if c == '\\':
                stack[-1]['parts'].append(text[i + 1])
                i += 2
                continue
            if '0' <= c <= '9':
                j = i + 1
                while j < n and '0' <= text[j] <= '9':
                    j += 1
                if j < n and text[j] == '[':
                    count = count_of(text[i:j])
                    if count == 0 or count is None:
                        # skip the bracketed content entirely (0 or huge count)
                        depth = 1
                        k = j + 1
                        while k < n and depth > 0:
                            ch = text[k]
                            if ch == '\\':
                                k += 2
                                continue
                            if ch == '[':
                                depth += 1
                            elif ch == ']':
                                depth -= 1
                            k += 1
                        i = k
                        continue
                    stack.append({'parts': [], 'count': count})
                    i = j + 1
                    continue
                stack[-1]['parts'].append(text[i:j])
                i = j
                continue
            if c == '[':
                raise Invalid()
            if c == ']':
                if len(stack) == 1:
                    raise Invalid()
                frame = stack.pop()
                content = ''.join(frame['parts'])
                count = frame['count']
                if count == 0:
                    contribution = ''
                else:
                    contribution = content * count
                stack[-1]['parts'].append(contribution)
                i += 1
                continue
            stack[-1]['parts'].append(c)
            i += 1
        if len(stack) != 1:
            raise Invalid()
    except Invalid:
        return None

    return ''.join(stack[0]['parts'])

def decode_repeat(text):
    LIMIT = 10000
    CAP = LIMIT + 1
    n = len(text)

    # Pass 1: validate and compute the decoded length (capped, never building oversized strings).
    stack = []
    current = 0
    i = 0
    while i < n:
        c = text[i]
        if c == '\\':
            if i + 1 >= n:
                return None
            if stack:
                v = stack[-1][1] + 1
                stack[-1][1] = v if v < CAP else CAP
            else:
                v = current + 1
                current = v if v < CAP else CAP
            i += 2
            continue
        if '0' <= c <= '9':
            j = i
            count = 0
            while j < n and '0' <= text[j] <= '9':
                count = count * 10 + (ord(text[j]) - 48)
                if count > CAP:
                    count = CAP
                j += 1
            if j < n and text[j] == '[':
                stack.append([count, 0])
                i = j + 1
                continue
            add = j - i
            if stack:
                v = stack[-1][1] + add
                stack[-1][1] = v if v < CAP else CAP
            else:
                v = current + add
                current = v if v < CAP else CAP
            i = j
            continue
        if c == '[':
            return None
        if c == ']':
