            stack[-1][1] = v if v < CAP else CAP
        else:
            v = current + 1
            current = v if v < CAP else CAP
        i += 1
    if stack:
        return None
    if current > LIMIT:
        return None

    # Pass 2: build the result (only reached when the result fits the limit).
    out = []
    stack = []
    i = 0
    while i < n:
        c = text[i]
        if c == '\\':
            if stack:
                stack[-1][1].append(text[i + 1])
            else:
                out.append(text[i + 1])
            i += 2
            continue
        if '0' <= c <= '9':
            j = i
            count = 0
            while j < n and '0' <= text[j] <= '9':
                count = count * 10 + (ord(text[j]) - 48)
                if count > CAP:
                    count = CAP
                j += 1
            if j < n and text[j] == '[':
                if count == 0:
                    k = j + 1
                    depth = 1
                    while k < n:
                        ck = text[k]
                        if ck == '\\':
                            k += 2
                            continue
                        if ck == '[':
                            depth += 1
                            k += 1
                            continue
                        if ck == ']':
                            depth -= 1
                            k += 1
                            if depth == 0:
                                break
                            continue
                        k += 1
                    i = k
                    continue
                stack.append([count, []])
                i = j + 1
                continue
            if stack:
                stack[-1][1].append(text[i:j])
            else:
                out.append(text[i:j])
            i = j
            continue
        if c == '[':
            return None
        if c == ']':
            if not stack:
                return None
            frame = stack.pop()
            count = frame[0]
            content = ''.join(frame[1])
            if count <= 1:
                contribution = content
            else:
                contribution = content * count
            if stack:
                stack[-1][1].append(contribution)
