def league_table(matches):
    valid = []
    for match in matches:
        home, away, home_goals, away_goals = match
        if home == away:
            continue
        if home_goals < 0 or away_goals < 0:
            continue
        valid.append((home, away, home_goals, away_goals))

    teams = {}

    def ensure(team):
        if team not in teams:
            teams[team] = {
                "played": 0,
                "won": 0,
                "drawn": 0,
                "lost": 0,
                "goals_for": 0,
                "goals_against": 0,
                "points": 0,
            }
        return teams[team]

    for home, away, home_goals, away_goals in valid:
        h = ensure(home)
        a = ensure(away)
        h["played"] += 1
        a["played"] += 1
        h["goals_for"] += home_goals
        h["goals_against"] += away_goals
        a["goals_for"] += away_goals
        a["goals_against"] += home_goals
        if home_goals > away_goals:
            h["won"] += 1
            h["points"] += 3
            a["lost"] += 1
        elif home_goals < away_goals:
            a["won"] += 1
            a["points"] += 3
            h["lost"] += 1
        else:
            h["drawn"] += 1
            a["drawn"] += 1
            h["points"] += 1
            a["points"] += 1

    groups = {}
    for team, stat in teams.items():
        groups.setdefault(stat["points"], []).append(team)

    h2h_points = {}
    h2h_gd = {}
    for group_teams in groups.values():
        group_set = set(group_teams)
        for team in group_teams:
            pts = 0
            gd = 0
            for home, away, home_goals, away_goals in valid:
                if home == team and away in group_set:
                    if home_goals > away_goals:
                        pts += 3
                    elif home_goals == away_goals:
                        pts += 1
                    gd += home_goals - away_goals
                elif away == team and home in group_set:
                    if away_goals > home_goals:
                        pts += 3
                    elif away_goals == home_goals:
                        pts += 1
                    gd += away_goals - home_goals
            h2h_points[team] = pts
            h2h_gd[team] = gd

    rows = []
    for team, stat in teams.items():
        rows.append({
            "name": team,
            "played": stat["played"],
            "won": stat["won"],
            "drawn": stat["drawn"],
            "lost": stat["lost"],
            "goals_for": stat["goals_for"],
            "goals_against": stat["goals_against"],
            "points": stat["points"],
            "h2h_points": h2h_points[team],
            "h2h_gd": h2h_gd[team],
            "gd": stat["goals_for"] - stat["goals_against"],
        })

    rows.sort(key=lambda r: (
        -r["points"],
        -r["h2h_points"],
        -r["h2h_gd"],
        -r["gd"],
        -r["goals_for"],
        r["name"],
    ))

    return [
        [r["name"], r["played"], r["won"], r["drawn"], r["lost"], r["goals_for"], r["goals_against"], r["points"]]
        for r in rows
    ]

