                if tok is not None and (tok[0] == '+' or tok[0] == '-'):
                    op = self.advance()[0]
                    rhs = self.parse_term()
                    node = ('bin', op, node, rhs)
                else:
                    return node

        def parse_term(self):
            node = self.parse_unary()
            while True:
                tok = self.peek()
                if tok is not None and tok[0] == '*':
                    self.advance()
                    rhs = self.parse_unary()
                    node = ('bin', '*', node, rhs)
                else:
                    return node

        def parse_unary(self):
            tok = self.peek()
            if tok is not None and tok[0] == '-':
                self.advance()
                operand = self.parse_unary()
                return ('neg', operand)
            return self.parse_primary()

        def parse_primary(self):
            tok = self.peek()
            if tok is None:
                raise ParseError()
            if tok[0] == 'INT':
                self.advance()
                return ('int', int(tok[1]))
            if tok[0] == 'REF':
                self.advance()
                return ('ref', tok[1])
            if tok[0] == 'SUM(':
                self.advance()
                left = self.expect_ref()
                self.expect(':')
                right = self.expect_ref()
                self.expect(')')
                return ('sum', left, right)
            if tok[0] == '(':
                self.advance()
                node = self.parse_expr()
                self.expect(')')
                return ('paren', node)
            raise ParseError()

    def parse_formula(s):
        tokens = tokenize(s)
        parser = Parser(tokens)
        node = parser.parse_expr()
        if parser.peek() is not None:
            raise ParseError()
        return node

    def col_row(name):
        return name[0], int(name[1:])

    def expanded_refs(left, right):
        left_col, left_row = col_row(left)
        right_col, right_row = col_row(right)
        min_col = min(left_col, right_col)
        max_col = max(left_col, right_col)
        min_row = min(left_row, right_row)
        max_row = max(left_row, right_row)
        refs = []
        for row in range(min_row, max_row + 1):
            for col in range(ord(min_col), ord(max_col) + 1):
                refs.append(chr(col) + str(row))
        return refs

    def refs_of(node):
        kind = node[0]
        if kind == 'int':
            return []
        if kind == 'ref':
            return [node[1]]
        if kind == 'sum':
            return expanded_refs(node[1], node[2])
        if kind == 'paren':
            return refs_of(node[1])
        if kind == 'neg':
            return refs_of(node[1])
        if kind == 'bin':
            return refs_of(node[2]) + refs_of(node[3])
        raise ParseError()

    def eval_node(node, value_of):
        kind = node[0]
        if kind == 'int':
            return node[1]
        if kind == 'ref':
            return value_of(node[1])
        if kind == 'sum':
            total = 0
            for name in expanded_refs(node[1], node[2]):
                total += value_of(name)
            return total
        if kind == 'paren':
            return eval_node(node[1], value_of)
        if kind == 'neg':
            return -eval_node(node[1], value_of)
        if kind == 'bin':
            op = node[1]
            left = eval_node(node[2], value_of)
            right = eval_node(node[3], value_of)
            if op == '+':
                return left + right
            if op == '-':
                return left - right
            if op == '*':
                return left * right
            raise ParseError()
        raise ParseError()

    def parse_cell(raw):
        if isinstance(raw, str) and raw.startswith('='):
            try:
                ast = parse_formula(raw[1:])
                return {'kind': 'formula', 'ast': ast, 'refs': refs_of(ast)}
            except ParseError:
                return {'kind': 'syntax'}
        value = parse_literal(raw)
        if value is not None:
            return {'kind': 'int', 'value': value}
        return {'kind': 'value_error'}

    parsed = {}
    for name, raw in cells.items():
        parsed[name] = parse_cell(raw)

    formula_nodes = [name for name, p in parsed.items() if p['kind'] == 'formula']
    formula_set = set(formula_nodes)
    refs = {name: parsed[name]['refs'] for name in formula_nodes}

    cyclic = set()
    for start in formula_nodes:
        if start in cyclic:
            continue
        seen = {start}
        stack = [start]
        is_cyclic = False
        while stack:
            node = stack.pop()
            for ref in refs[node]:
                if ref == start:
                    is_cyclic = True
                    break
                if ref in formula_set and ref not in seen:
                    seen.add(ref)
                    stack.append(ref)
            if is_cyclic:
                break
        if is_cyclic:
            cyclic.add(start)

    memo = {}

    def value_of(name):
        p = parsed.get(name)
        if p is None:
            return 0
        if p['kind'] == 'int':
            return p['value']
        if p['kind'] == 'value_error':
            return '#VALUE'
        if p['kind'] == 'syntax':
            return '#SYNTAX'
        if name in cyclic:
            return '#CYCLE'
        if name in memo:
            return memo[name]
        for ref in p['refs']:
            value = value_of(ref)
            if isinstance(value, str):
                memo[name] = value
                return value
        value = eval_node(p['ast'], value_of)
        memo[name] = value
        return value

    result = {}
    for name in cells:
        result[name] = value_of(name)
    return result

def spreadsheet_eval(cells):
    def is_literal(raw):
        s = raw[1:] if raw.startswith('-') else raw
        if not s:
            return False
        return all('0' <= ch <= '9' for ch in s)

    def tokenize(s):
        tokens = []
        i = 0
        n = len(s)
        while i < n:
            c = s[i]
            if c == ' ':
                i += 1
                continue
            if s.startswith('SUM(', i):
                tokens.append('SUM(')
                i += 4
                continue
            if c == '(' or c == ')' or c == ':':
                tokens.append(c)
                i += 1
                continue
            if c == '+' or c == '-' or c == '*':
                tokens.append(c)
                i += 1
                continue
            if '0' <= c <= '9':
                j = i
                while j < n and '0' <= s[j] <= '9':
                    j += 1
                tokens.append(('num', int(s[i:j])))
                i = j
                continue
            if 'A' <= c <= 'Z':
                j = i + 1
                k = j
                while k < n and '0' <= s[k] <= '9':
                    k += 1
                if k == j:
                    raise SyntaxError('bad reference')
                row_str = s[j:k]
                if row_str[0] == '0' or len(row_str) > 2:
                    raise SyntaxError('bad row')
                row = int(row_str)
                if row < 1 or row > 99:
                    raise SyntaxError('bad row')
                tokens.append(('ref', c + row_str))
                i = k
                continue
            raise SyntaxError('unexpected character')
        return tokens

    def parse_formula(s):
        try:
            tokens = tokenize(s)
            pos = 0

            def peek():
                return tokens[pos] if pos < len(tokens) else None

            def advance():
                nonlocal pos
                t = tokens[pos]
                pos += 1
                return t

            def parse_expr():
                node = parse_term()
                while peek() == '+' or peek() == '-':
                    op = advance()
                    rhs = parse_term()
                    node = ('bin', op, node, rhs)
                return node

            def parse_term():
                node = parse_unary()
                while peek() == '*':
                    advance()
                    rhs = parse_unary()
                    node = ('bin', '*', node, rhs)
                return node

            def parse_unary():
                if peek() == '-':
                    advance()
                    return ('neg', parse_unary())
                return parse_primary()

            def parse_primary():
                t = peek()
                if t is None:
                    raise SyntaxError('unexpected end')
                if isinstance(t, tuple):
                    if t[0] == 'num':
                        advance()
                        return ('int', t[1])
                    if t[0] == 'ref':
                        advance()
                        return ('ref', t[1])
                    raise SyntaxError('unexpected token')
                if t == 'SUM(':
                    advance()
                    c1 = expect_ref()
                    if advance() != ':':
                        raise SyntaxError('expected colon')
                    c2 = expect_ref()
                    if advance() != ')':
                        raise SyntaxError('expected )')
                    return ('sum', c1, c2)
                if t == '(':
                    advance()
                    node = parse_expr()
                    if advance() != ')':
                        raise SyntaxError('expected )')
                    return node
                raise SyntaxError('unexpected token')

            def expect_ref():
                t = advance()
                if isinstance(t, tuple) and t[0] == 'ref':
                    return t[1]
                raise SyntaxError('expected reference')

            node = parse_expr()
            if pos != len(tokens):
                raise SyntaxError('trailing tokens')
            return node
        except (SyntaxError, IndexError):
            raise SyntaxError('invalid formula')

    def expand_sum(c1, c2):
        col1 = ord(c1[0]) - 65
        row1 = int(c1[1:])
        col2 = ord(c2[0]) - 65
        row2 = int(c2[1:])
        out = []
        for row in range(min(row1, row2), max(row1, row2) + 1):
            for col in range(min(col1, col2), max(col1, col2) + 1):
                out.append(chr(65 + col) + str(row))
        return out

    def ast_refs(node):
        kind = node[0]
        if kind == 'int':
            return []
        if kind == 'ref':
            return [node[1]]
        if kind == 'sum':
            return expand_sum(node[1], node[2])
        if kind == 'neg':
            return ast_refs(node[1])
        if kind == 'bin':
            return ast_refs(node[2]) + ast_refs(node[3])
        return []

    def reaches_self(name, formulas):
        seen = set()
        stack = list(formulas[name][1])
        while stack:
            c = stack.pop()
            if c == name:
                return True
            if c in seen:
                continue
            fc = formulas.get(c)
            if fc is None:
                continue
            ast, refs = fc
            if ast is None:
                continue
            seen.add(c)
            stack.extend(refs)
        return False

    def eval_ast(node, get_value):
        kind = node[0]
        if kind == 'int':
            return node[1]
        if kind == 'ref':
            return get_value(node[1])
        if kind == 'sum':
            total = 0
            for cell in expand_sum(node[1], node[2]):
                total += get_value(cell)
            return total
        if kind == 'neg':
            return -eval_ast(node[1], get_value)
        if kind == 'bin':
            lv = eval_ast(node[2], get_value)
            rv = eval_ast(node[3], get_value)
            op = node[1]
            if op == '+':
                return lv + rv
            if op == '-':
                return lv - rv
            return lv * rv
        raise SyntaxError('invalid node')

    values = {}
    formulas = {}
    for name, raw in cells.items():
        if not raw.startswith('='):
            if is_literal(raw):
                values[name] = int(raw)
            else:
                values[name] = '#VALUE'
        else:
            try:
                ast = parse_formula(raw[1:])
            except SyntaxError:
                formulas[name] = (None, [])
                values[name] = '#SYNTAX'
            else:
                formulas[name] = (ast, ast_refs(ast))

    cyclic = set()
    for name, (ast, refs) in formulas.items():
        if ast is None:
            continue
        if reaches_self(name, formulas):
            cyclic.add(name)
    for name in cyclic:
        values[name] = '#CYCLE'

    memo = {}

    def get_value(name):
        if name not in cells:
            return 0
        if name in memo:
            return memo[name]
        f = formulas.get(name)
        if f is None:
            v = values[name]
            memo[name] = v
            return v
        ast, refs = f
        if ast is None:
            v = '#SYNTAX'
        elif name in cyclic:
            v = '#CYCLE'
        else:
            v = None
            for r in refs:
                rv = get_value(r)
                if isinstance(rv, str):
                    v = rv
                    break
            if v is None:
                v = eval_ast(ast, get_value)
        memo[name] = v
        return v

    result = {}
    for name in cells:
        result[name] = get_value(name)
    return result

