import re
import sys


def _tokenize(s):
    tokens = []
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c == ' ':
            i += 1
            continue
        if s.startswith('SUM(', i):
            tokens.append(('SUM', 'SUM('))
            i += 4
            continue
        if '0' <= c <= '9':
            j = i
            while j < n and '0' <= s[j] <= '9':
                j += 1
            tokens.append(('NUM', int(s[i:j])))
            i = j
            continue
        if 'A' <= c <= 'Z':
            j = i + 1
            k = j
            while k < n and '0' <= s[k] <= '9':
                k += 1
            row = s[j:k]
            if not row or row[0] == '0':
                return None
            if not (1 <= int(row) <= 99):
                return None
            tokens.append(('REF', c + row))
            i = k
            continue
        if c in '+-*():':
            tokens.append((c, c))
            i += 1
            continue
        return None
    return tokens


def _parse_formula(s):
    tokens = _tokenize(s)
    if not tokens:
        return None
    n = len(tokens)
    pos = 0

    def peek():
        if pos < n:
            return tokens[pos][0]
        return None

    def next_tok():
        nonlocal pos
        t = tokens[pos]
        pos += 1
        return t

    def parse_expr():
        node = parse_term()
        while peek() == '+' or peek() == '-':
            op = next_tok()[0]
            rhs = parse_term()
            node = (op, node, rhs)
        return node

    def parse_term():
        node = parse_unary()
        while peek() == '*':
            next_tok()
            rhs = parse_unary()
            node = ('*', node, rhs)
        return node

    def parse_unary():
        if peek() == '-':
            next_tok()
            return ('neg', parse_unary())
        return parse_primary()

    def parse_ref():
        if peek() != 'REF':
            raise SyntaxError
        return next_tok()[1]

    def parse_primary():
        p = peek()
        if p == 'NUM':
            return ('num', next_tok()[1])
        if p == 'REF':
            return ('ref', next_tok()[1])
        if p == 'SUM':
            next_tok()
            a = parse_ref()
            if peek() != ':':
                raise SyntaxError
            next_tok()
            b = parse_ref()
            if peek() != ')':
                raise SyntaxError
            next_tok()
            return ('sum', a, b)
        if p == '(':
            next_tok()
            node = parse_expr()
            if peek() != ')':
                raise SyntaxError
            next_tok()
            return node
        raise SyntaxError

    try:
        node = parse_expr()
        if pos != n:
            return None
        return node
    except Exception:
        return None


def _expand_range(a, b):
    col1 = ord(a[0])
    row1 = int(a[1:])
    col2 = ord(b[0])
    row2 = int(b[1:])
    out = []
    for r in range(min(row1, row2), max(row1, row2) + 1):
        for c in range(min(col1, col2), max(col1, col2) + 1):
            out.append(chr(c) + str(r))
    return out


def _collect_refs(node):
    tag = node[0]
    if tag == 'ref':
        return [node[1]]
    if tag == 'num':
        return []
    if tag == 'neg':
        return _collect_refs(node[1])
    if tag == 'sum':
        return _expand_range(node[1], node[2])
    return _collect_refs(node[1]) + _collect_refs(node[2])


def _eval_ast(node, get_value):
    tag = node[0]
    if tag == 'num':
        return node[1]
    if tag == 'ref':
        return get_value(node[1])
    if tag == 'neg':
        return -_eval_ast(node[1], get_value)
    if tag == 'sum':
        total = 0
        for cell in _expand_range(node[1], node[2]):
            total += get_value(cell)
        return total
    left = _eval_ast(node[1], get_value)
    right = _eval_ast(node[2], get_value)
    if tag == '+':
        return left + right
    if tag == '-':
        return left - right
    return left * right


def spreadsheet_eval(cells):
    sys.setrecursionlimit(max(sys.getrecursionlimit(), 100000))
    is_formula = {}
    ast = {}
    refs = {}
    literal_value = {}

    for key, raw in cells.items():
        if raw.startswith('='):
            is_formula[key] = True
            node = _parse_formula(raw[1:])
            ast[key] = node
            refs[key] = _collect_refs(node) if node is not None else []
        else:
