        else:
            formulas[key] = ast

    refs_map = {}
    for key, ast in formulas.items():
        refs_map[key] = _refs_of(ast)

    formula_keys = set(formulas)
    cycle = set()
    for key in formulas:
        if _reaches_self(key, refs_map, formula_keys):
            cycle.add(key)

    values = dict(literal_values)
    for key in formulas:
        if key in cycle:
            values[key] = '#CYCLE'

    def cell_value(name):
        v = values.get(name)
        if v is not None:
            return v
        if name not in cells:
            return 0
        ast = formulas[name]
        for r in refs_map[name]:
            rv = cell_value(r)
            if isinstance(rv, str):
                values[name] = rv
                return rv
        v = _eval_ast(ast, cell_value)
        values[name] = v
        return v

    for key in formulas:
        if key not in cycle:
            cell_value(key)

    return {key: values[key] for key in cells}

