                j = i
                while j < n and '0' <= s[j] <= '9':
                    j += 1
                tokens.append(s[i:j])
                i = j
                continue
            if c in '+-*:()':
                tokens.append(c)
                i += 1
                continue
            if 'A' <= c <= 'Z':
