            return tokens[pos] if pos < len(tokens) else None

        def advance():
            nonlocal pos
            tok = tokens[pos]
            pos += 1
            return tok

        def parse_expr():
            node = parse_term()
            while peek() in ('+', '-'):
                op = advance()
                rhs = parse_term()
                node = ('bin', op, node, rhs)
            return node

        def parse_term():
            node = parse_unary()
            while peek() == '*':
                advance()
                rhs = parse_unary()
                node = ('bin', '*', node, rhs)
            return node

        def parse_unary():
            if peek() == '-':
                advance()
                return ('neg', parse_unary())
            return parse_primary()

        def parse_primary():
            tok = peek()
            if tok is None:
                raise SyntaxError('unexpected end')
            if INT_RE.fullmatch(tok):
                advance()
                return ('int', int(tok))
            if REF_RE.fullmatch(tok):
