                return ('ref', tok)
            if tok == 'SUM(':
                advance()
                r1 = peek()
                if r1 is None or not REF_RE.fullmatch(r1):
                    raise SyntaxError('bad SUM first ref')
                advance()
                if peek() != ':':
                    raise SyntaxError('expected :')
                advance()
                r2 = peek()
                if r2 is None or not REF_RE.fullmatch(r2):
                    raise SyntaxError('bad SUM second ref')
                advance()
                if peek() != ')':
                    raise SyntaxError('expected )')
                advance()
                return ('sum', r1, r2)
            if tok == '(':
                advance()
                node = parse_expr()
                if peek() != ')':
                    raise SyntaxError('expected )')
                advance()
                return node
            raise SyntaxError('unexpected token')

