            cur = stack.pop()
            if cur == name:
                found = True
                break
            if cur in seen:
                continue
            seen.add(cur)
            ast2 = asts.get(cur)
            if ast2 is not None:
                for ref in refs[cur]:
                    if ref not in seen:
