            return memo[name]
        if name not in cells:
            return 0
        raw = cells[name]
        if not raw.startswith('='):
            v = literal(raw)
            memo[name] = v
            return v
        ast = asts.get(name)
        if ast is None:
            v = '#SYNTAX'
            memo[name] = v
