                    v = values.pop()
                    if isinstance(v, str):
                        values.append(v)
                    else:
                        values.append(-v)
                elif node[0] == 'bin':
                    right = values.pop()
                    left = values.pop()
                    if isinstance(left, str):
                        values.append(left)
                    elif isinstance(right, str):
                        values.append(right)
                    else:
                        op = node[1]
                        if op == '+':
                            values.append(left + right)
                        elif op == '-':
                            values.append(left - right)
                        elif op == '*':
                            values.append(left * right)
