def spreadsheet_eval(cells):
    def _tokenize(s):
        tokens = []
        i = 0
        n = len(s)
        while i < n:
            c = s[i]
            if c == ' ':
                i += 1
                continue
            if c == 'S' and s.startswith('SUM(', i):
                tokens.append(('SUM',))
                i += 4
                continue
            if c.isdigit():
                j = i
                while j < n and s[j].isdigit():
                    j += 1
                tokens.append(('INT', int(s[i:j])))
                i = j
                continue
            if c in '-+*:()':
                tokens.append((c,))
                i += 1
                continue
            if 'A' <= c <= 'Z':
                j = i + 1
                while j < n and s[j].isdigit():
                    j += 1
                if j == i + 1:
                    raise ValueError('invalid REF')
                digits = s[i + 1:j]
                if digits[0] == '0':
                    raise ValueError('invalid row')
                row = int(digits)
                if row < 1 or row > 99:
                    raise ValueError('invalid row')
                tokens.append(('REF', c + digits))
                i = j
                continue
            raise ValueError('invalid char')
        return tokens

    def _parse_formula(s):
        try:
            tokens = _tokenize(s)
        except ValueError:
            return None
        pos = 0

        def peek():
            if pos < len(tokens):
                return tokens[pos]
            return None

        def advance():
            nonlocal pos
            if pos >= len(tokens):
                raise ValueError('unexpected end')
            tok = tokens[pos]
            pos += 1
            return tok

        def parse_expr():
            left = parse_term()
            while peek() is not None and peek()[0] in ('+', '-'):
                op = advance()[0]
                right = parse_term()
                left = ('bin', op, left, right)
            return left

        def parse_term():
            left = parse_unary()
            while peek() is not None and peek()[0] == '*':
                advance()
                right = parse_unary()
                left = ('bin', '*', left, right)
            return left

        def parse_unary():
            if peek() is not None and peek()[0] == '-':
                advance()
                operand = parse_unary()
                return ('neg', operand)
            return parse_primary()

        def parse_primary():
            tok = advance()
            kind = tok[0]
            if kind == 'INT':
                return ('int', tok[1])
            if kind == 'REF':
                return ('ref', tok[1])
            if kind == 'SUM':
                t = advance()
                if t[0] != 'REF':
                    raise ValueError('expected REF')
                ref1 = t[1]
                t = advance()
                if t[0] != ':':
                    raise ValueError('expected :')
                t = advance()
                if t[0] != 'REF':
                    raise ValueError('expected REF')
                ref2 = t[1]
                t = advance()
                if t[0] != ')':
                    raise ValueError('expected )')
                return ('sum', ref1, ref2)
            if kind == '(':
                e = parse_expr()
                t = advance()
                if t[0] != ')':
                    raise ValueError('expected )')
                return e
            raise ValueError('unexpected token')

        try:
            node = parse_expr()
            if pos != len(tokens):
                return None
            return node
        except ValueError:
            return None

    def _expand(ref1, ref2):
        col1, row1 = ref1[0], int(ref1[1:])
        col2, row2 = ref2[0], int(ref2[1:])
        top, bottom = min(row1, row2), max(row1, row2)
        left, right = min(col1, col2), max(col1, col2)
        out = []
        for row in range(top, bottom + 1):
            for col in range(ord(left), ord(right) + 1):
                out.append(f'{chr(col)}{row}')
        return out

    def _refs_of(node):
        refs = []
        stack = [node]
        while stack:
            cur = stack.pop()
            tag = cur[0]
            if tag == 'int':
                continue
            if tag == 'ref':
                refs.append(cur[1])
                continue
            if tag == 'sum':
                refs.extend(_expand(cur[1], cur[2]))
                continue
            if tag == 'neg':
                stack.append(cur[1])
                continue
            if tag == 'bin':
                stack.append(cur[3])
                stack.append(cur[2])
                continue
        return refs

    def _eval_node(node, get):
        post = []
        stack = [(node, False)]
        while stack:
            cur, processed = stack.pop()
            if processed:
                post.append(cur)
                continue
            tag = cur[0]
            if tag in ('int', 'ref', 'sum'):
                post.append(cur)
                continue
            if tag == 'neg':
                stack.append((cur, True))
                stack.append((cur[1], False))
                continue
            if tag == 'bin':
                stack.append((cur, True))
                stack.append((cur[3], False))
                stack.append((cur[2], False))
                continue
        values = []
        for cur in post:
            tag = cur[0]
            if tag == 'int':
                values.append(cur[1])
            elif tag == 'ref':
                values.append(get(cur[1]))
            elif tag == 'sum':
                total = 0
                for cell in _expand(cur[1], cur[2]):
                    total += get(cell)
                values.append(total)
            elif tag == 'neg':
                values.append(-values.pop())
            elif tag == 'bin':
                r = values.pop()
                l = values.pop()
                op = cur[1]
                if op == '+':
                    values.append(l + r)
                elif op == '-':
                    values.append(l - r)
                else:
                    values.append(l * r)
        return values.pop()

    formula_nodes = {}
    formula_refs = {}
    parse_fail = set()

    for name, raw in cells.items():
        if not raw.startswith('='):
            continue
        node = _parse_formula(raw[1:])
        if node is None:
            parse_fail.add(name)
        else:
            formula_nodes[name] = node
            formula_refs[name] = _refs_of(node)

    cycle_set = set()
    for name in formula_nodes:
        visited = set()
        stack = [r for r in formula_refs[name] if r in formula_nodes]
        found = False
        while stack:
            cur = stack.pop()
            if cur == name:
                found = True
                break
            if cur in visited:
                continue
            visited.add(cur)
            for r in formula_refs[cur]:
                if r in formula_nodes:
                    stack.append(r)
        if found:
            cycle_set.add(name)

    memo = {}
    for name, raw in cells.items():
        if not raw.startswith('='):
            if re.fullmatch(r'-?[0-9]+', raw):
                memo[name] = int(raw)
            else:
                memo[name] = '#VALUE'
        else:
            if name in cycle_set:
                memo[name] = '#CYCLE'
            elif name in parse_fail:
                memo[name] = '#SYNTAX'

    def _eval_formula(name):
        refs = formula_refs[name]
        for r in refs:
            if r in cells:
                v = memo.get(r)
                if isinstance(v, str):
                    return v
        node = formula_nodes[name]
        return _eval_node(node, lambda nm: memo.get(nm, 0))

    def value(name):
        if name in memo:
            return memo[name]
        stack = [(name, False)]
        while stack:
            cur, expanded = stack.pop()
            if cur in memo:
                continue
            if expanded:
                memo[cur] = _eval_formula(cur)
                continue
            stack.append((cur, True))
            for r in formula_refs[cur]:
                if r in cells and r not in memo:
                    if cells[r].startswith('=') and r not in cycle_set and r not in parse_fail:
                        stack.append((r, False))
        return memo[name]

    result = {}
    for name in cells:
        result[name] = value(name)
    return result

