import sys

def spreadsheet_eval(cells):
    sys.setrecursionlimit(100000)

    def tokenize(body):
        tokens = []
        i = 0
        n = len(body)
        while i < n:
            c = body[i]
            if c == ' ':
                i += 1
                continue
            if c == '+':
                tokens.append(('plus', None)); i += 1
            elif c == '-':
                tokens.append(('minus', None)); i += 1
            elif c == '*':
                tokens.append(('star', None)); i += 1
            elif c == '(':
                tokens.append(('lp', None)); i += 1
            elif c == ')':
                tokens.append(('rp', None)); i += 1
            elif c == ':':
                tokens.append(('colon', None)); i += 1
            elif c == 'S' and body.startswith('SUM(', i):
                tokens.append(('sum', None)); i += 4
            elif '0' <= c <= '9':
                j = i
                while j < n and '0' <= body[j] <= '9':
                    j += 1
                tokens.append(('num', int(body[i:j])))
                i = j
            elif 'A' <= c <= 'Z':
                j = i + 1
                while j < n and '0' <= body[j] <= '9':
                    j += 1
                if j == i + 1:
                    raise SyntaxError
                digits = body[i + 1:j]
                if len(digits) > 1 and digits.startswith('0'):
                    raise SyntaxError
                r = int(digits)
                if r < 1 or r > 99:
                    raise SyntaxError
                tokens.append(('ref', c + digits))
                i = j
            else:
                raise SyntaxError
        return tokens

    def expand_sum(r1, r2):
        col1 = r1[0]; row1 = int(r1[1:])
        col2 = r2[0]; row2 = int(r2[1:])
        c0 = min(col1, col2); c1 = max(col1, col2)
        r0 = min(row1, row2); r1m = max(row1, row2)
        out = []
        for row in range(r0, r1m + 1):
            for ci in range(ord(c0), ord(c1) + 1):
                out.append(chr(ci) + str(row))
        return out

    def collect_refs(node):
        kind = node[0]
        if kind == 'num':
            return []
        if kind == 'ref':
            return [node[1]]
        if kind == 'sum':
            return list(node[1])
        if kind == 'neg':
            return collect_refs(node[1])
        return collect_refs(node[1]) + collect_refs(node[2])

    def eval_ast(node, get_value):
        kind = node[0]
        if kind == 'num':
            return node[1]
        if kind == 'ref':
            return get_value(node[1])
        if kind == 'sum':
            total = 0
            for c in node[1]:
                total += get_value(c)
            return total
        if kind == 'neg':
            return -eval_ast(node[1], get_value)
        if kind == 'add':
            return eval_ast(node[1], get_value) + eval_ast(node[2], get_value)
        if kind == 'sub':
            return eval_ast(node[1], get_value) - eval_ast(node[2], get_value)
        if kind == 'mul':
            return eval_ast(node[1], get_value) * eval_ast(node[2], get_value)
        raise SyntaxError

    class Parser:
        def __init__(self, tokens):
            self.tokens = tokens
            self.pos = 0
        def peek(self):
            if self.pos < len(self.tokens):
                return self.tokens[self.pos]
            return None
        def next(self):
            tok = self.tokens[self.pos]
            self.pos += 1
            return tok
        def expect(self, kind):
            tok = self.peek()
            if tok is None or tok[0] != kind:
                raise SyntaxError
            self.next()
        def expect_ref(self):
            tok = self.peek()
            if tok is None or tok[0] != 'ref':
                raise SyntaxError
            self.next()
            return tok[1]
        def parse_expr(self):
            left = self.parse_term()
            while True:
                tok = self.peek()
                if tok is not None and tok[0] == 'plus':
                    self.next()
                    right = self.parse_term()
                    left = ('add', left, right)
                elif tok is not None and tok[0] == 'minus':
                    self.next()
                    right = self.parse_term()
                    left = ('sub', left, right)
                else:
                    return left
        def parse_term(self):
            left = self.parse_unary()
            while True:
                tok = self.peek()
                if tok is not None and tok[0] == 'star':
                    self.next()
                    right = self.parse_unary()
                    left = ('mul', left, right)
                else:
                    return left
        def parse_unary(self):
            tok = self.peek()
            if tok is not None and tok[0] == 'minus':
                self.next()
                return ('neg', self.parse_unary())
            return self.parse_primary()
        def parse_primary(self):
            tok = self.peek()
            if tok is None:
                raise SyntaxError
            kind = tok[0]
            if kind == 'num':
                self.next()
                return ('num', tok[1])
            if kind == 'ref':
                self.next()
                return ('ref', tok[1])
            if kind == 'sum':
                self.next()
                r1 = self.expect_ref()
                self.expect('colon')
                r2 = self.expect_ref()
                self.expect('rp')
                return ('sum', expand_sum(r1, r2))
            if kind == 'lp':
                self.next()
                node = self.parse_expr()
                self.expect('rp')
                return node
            raise SyntaxError

    def parse_formula(body):
        tokens = tokenize(body)
        parser = Parser(tokens)
        node = parser.parse_expr()
        if parser.pos != len(tokens):
            raise SyntaxError
        return node, collect_refs(node)

    static_value = {}
    ast_map = {}
    refs_map = {}
    parsed_names = []

    for name, raw in cells.items():
        if not raw.startswith('='):
            if re.fullmatch(r'-?[0-9]+', raw):
                static_value[name] = int(raw)
            else:
                static_value[name] = '#VALUE'
        else:
            try:
                ast, refs = parse_formula(raw[1:])
            except SyntaxError:
                static_value[name] = '#SYNTAX'
            else:
                ast_map[name] = ast
                refs_map[name] = refs
                parsed_names.append(name)

    cyclic_set = set()
    for cell in parsed_names:
        seen = set()
        stack = [cell]
        found = False
        while stack:
            c = stack.pop()
            for r in refs_map.get(c, ()):
                if r == cell:
                    found = True
                    break
                if r not in seen:
                    seen.add(r)
                    stack.append(r)
            if found:
                break
        if found:
            cyclic_set.add(cell)

    memo = {}

    def get_value(name):
        if name in memo:
            return memo[name]
        if name not in cells:
            memo[name] = 0
            return 0
        if name in static_value:
            memo[name] = static_value[name]
            return memo[name]
        if name in cyclic_set:
            memo[name] = '#CYCLE'
            return '#CYCLE'
        refs = refs_map[name]
        for r in refs:
            v = get_value(r)
            if isinstance(v, str):
                memo[name] = v
                return v
        value = eval_ast(ast_map[name], get_value)
        memo[name] = value
        return value

    result = {}
    for name in cells:
        result[name] = get_value(name)
    return result

