from collections import deque

_LIT_RE = re.compile(r'-?[0-9]+')
_INT_RE = re.compile(r'[0-9]+')
_REF_RE = re.compile(r'[A-Z][1-9][0-9]?')


def _tokenize(s):
    tokens = []
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c.isspace():
            i += 1
            continue
        if s.startswith('SUM(', i):
            tokens.append('SUM(')
            i += 4
            continue
        if '0' <= c <= '9':
            j = i
            while j < n and '0' <= s[j] <= '9':
                j += 1
            tokens.append(s[i:j])
            i = j
            continue
        if 'A' <= c <= 'Z':
            j = i + 1
            while j < n and '0' <= s[j] <= '9':
                j += 1
            tokens.append(s[i:j])
            i = j
            continue
        if c in '+-*():':
            tokens.append(c)
            i += 1
            continue
        raise ValueError('unexpected character')
    return tokens


def _parse_tokens(tokens):
    pos = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else None

    def parse_expr():
        nonlocal pos
        node = parse_term()
        while peek() in ('+', '-'):
            op = tokens[pos]
            pos += 1
            rhs = parse_term()
            node = ('bin', op, node, rhs)
        return node

    def parse_term():
        nonlocal pos
        node = parse_unary()
        while peek() == '*':
            pos += 1
            rhs = parse_unary()
            node = ('mul', node, rhs)
        return node

    def parse_unary():
        nonlocal pos
        if peek() == '-':
            pos += 1
            return ('neg', parse_unary())
        return parse_primary()

    def parse_primary():
        nonlocal pos
        t = peek()
        if t is None:
            raise ValueError('unexpected end of formula')
        if t == 'SUM(':
            pos += 1
            r1 = peek()
            if r1 is None or not _REF_RE.fullmatch(r1):
                raise ValueError('expected reference after SUM(')
            pos += 1
            if peek() != ':':
                raise ValueError('expected :')
            pos += 1
            r2 = peek()
            if r2 is None or not _REF_RE.fullmatch(r2):
                raise ValueError('expected reference after :')
            pos += 1
            if peek() != ')':
                raise ValueError('expected )')
            pos += 1
            return ('sum', r1, r2)
        if _INT_RE.fullmatch(t):
            pos += 1
            return ('int', int(t))
        if _REF_RE.fullmatch(t):
            pos += 1
            return ('ref', t)
        if t == '(':
            pos += 1
            node = parse_expr()
            if peek() != ')':
                raise ValueError('expected )')
            pos += 1
            return node
        raise ValueError('unexpected token')

    node = parse_expr()
    if pos != len(tokens):
        raise ValueError('trailing tokens')
    return node


def _try_parse(s):
    try:
        return _parse_tokens(_tokenize(s))
    except Exception:
        return None


def _expand(r1, r2):
    c1 = ord(r1[0])
    row1 = int(r1[1:])
    c2 = ord(r2[0])
    row2 = int(r2[1:])
    cols = range(min(c1, c2), max(c1, c2) + 1)
    rows = range(min(row1, row2), max(row1, row2) + 1)
    out = []
    for row in rows:
        for col in cols:
            out.append(chr(col) + str(row))
    return out


def _refs_of(node):
    tag = node[0]
    if tag == 'int':
        return []
    if tag == 'ref':
        return [node[1]]
    if tag == 'neg':
        return _refs_of(node[1])
    if tag == 'bin':
        return _refs_of(node[2]) + _refs_of(node[3])
    if tag == 'mul':
        return _refs_of(node[1]) + _refs_of(node[2])
    if tag == 'sum':
        return _expand(node[1], node[2])
    raise ValueError('bad node')


def _eval_node(node, value_of):
    tag = node[0]
    if tag == 'int':
        return node[1]
    if tag == 'ref':
        return value_of(node[1])
    if tag == 'neg':
        return -_eval_node(node[1], value_of)
    if tag == 'bin':
        lv = _eval_node(node[2], value_of)
        rv = _eval_node(node[3], value_of)
        return lv + rv if node[1] == '+' else lv - rv
    if tag == 'mul':
        return _eval_node(node[1], value_of) * _eval_node(node[2], value_of)
    if tag == 'sum':
        total = 0
        for ref in _expand(node[1], node[2]):
            total += value_of(ref)
        return total
    raise ValueError('bad node')


def _can_reach_self(name, ref_lists, formula_names):
    seen = set()
    stack = [name]
    while stack:
        cur = stack.pop()
        for ref in ref_lists[cur]:
            if ref in formula_names:
                if ref == name:
                    return True
                if ref not in seen:
                    seen.add(ref)
                    stack.append(ref)
    return False


def spreadsheet_eval(cells):
    results = {}
    parsed = {}
    for name, raw in cells.items():
        if not isinstance(raw, str):
            results[name] = '#VALUE'
            continue
        if not raw.startswith('='):
            if _LIT_RE.fullmatch(raw):
                results[name] = int(raw)
            else:
                results[name] = '#VALUE'
            continue
        node = _try_parse(raw[1:])
        if node is None:
            results[name] = '#SYNTAX'
        else:
            parsed[name] = node

    ref_lists = {}
    for name, node in parsed.items():
        ref_lists[name] = _refs_of(node)

    formula_names = set(parsed)
    cycle_names = set()
    for name in parsed:
        if _can_reach_self(name, ref_lists, formula_names):
            cycle_names.add(name)
    for name in cycle_names:
        results[name] = '#CYCLE'

    non_cycle = [n for n in parsed if n not in cycle_names]
    non_cycle_set = set(non_cycle)
    indeg = {}
    out = {}
    for name in non_cycle:
        deps = set(r for r in ref_lists[name] if r in non_cycle_set)
        indeg[name] = len(deps)
        for d in deps:
            out.setdefault(d, []).append(name)

    queue = deque([n for n in non_cycle if indeg[n] == 0])
    order = []
    while queue:
        n = queue.popleft()
        order.append(n)
        for m in out.get(n, ()):
            indeg[m] -= 1
            if indeg[m] == 0:
                queue.append(m)

    for name in order:
        refs = ref_lists[name]
        first_err = None
        for ref in refs:
            v = results.get(ref, 0)
            if isinstance(v, str):
                first_err = v
                break
        if first_err is not None:
            results[name] = first_err
            continue
        results[name] = _eval_node(parsed[name], lambda r: results.get(r, 0))

    return {name: results[name] for name in cells}

def spreadsheet_eval(cells):
    def parse_literal(s):
        if s == '':
            return '#VALUE'
        i = 0
        if s[0] == '-':
            i = 1
        if i >= len(s):
            return '#VALUE'
        for ch in s[i:]:
            if not ('0' <= ch <= '9'):
                return '#VALUE'
