    def tokenize(text):
        tokens = []
        i = 0
        n = len(text)
        while i < n:
            ch = text[i]
            if ch.isspace():
                i += 1
                continue
            if ch in '+-*():':
                tokens.append(ch)
                i += 1
                continue
            if '0' <= ch <= '9':
                j = i
                while j < n and '0' <= text[j] <= '9':
                    j += 1
                tokens.append(('int', int(text[i:j])))
                i = j
                continue
            if ch == 'S' and text.startswith('SUM(', i):
                tokens.append('SUM(')
                i += 4
                continue
            if 'A' <= ch <= 'Z':
                j = i + 1
                k = j
                while k < n and '0' <= text[k] <= '9':
                    k += 1
                if k == j:
                    return None
                row = text[j:k]
                if not ((len(row) == 1 and '1' <= row[0] <= '9') or
                        (len(row) == 2 and '1' <= row[0] <= '9' and '0' <= row[1] <= '9')):
                    return None
                tokens.append(('ref', ch + row))
                i = k
                continue
            return None
        return tokens

    def parse_formula(text):
