        if tokens is None:
            return None
        pos = 0

        def peek():
            return tokens[pos] if pos < len(tokens) else None

        def advance():
            nonlocal pos
            t = tokens[pos]
            pos += 1
            return t

        def parse_expr():
            node = parse_term()
            if node is None:
                return None
            while peek() in ('+', '-'):
                op = advance()
                rhs = parse_term()
                if rhs is None:
                    return None
                node = ('bin', op, node, rhs)
            return node

        def parse_term():
            node = parse_unary()
            if node is None:
                return None
            while peek() == '*':
                advance()
                rhs = parse_unary()
                if rhs is None:
                    return None
                node = ('bin', '*', node, rhs)
            return node

        def parse_unary():
            if peek() == '-':
                advance()
                operand = parse_unary()
                if operand is None:
                    return None
                return ('neg', operand)
            return parse_primary()

        def parse_primary():
            t = peek()
            if t is None:
                return None
            if isinstance(t, tuple):
                if t[0] == 'int':
                    advance()
                    return ('int', t[1])
                if t[0] == 'ref':
                    advance()
                    return ('ref', t[1])
                return None
            if t == 'SUM(':
                advance()
                r1 = peek()
                if not (isinstance(r1, tuple) and r1[0] == 'ref'):
                    return None
                advance()
                if peek() != ':':
                    return None
                advance()
                r2 = peek()
                if not (isinstance(r2, tuple) and r2[0] == 'ref'):
                    return None
                advance()
                if peek() != ')':
                    return None
                advance()
                return ('sum', r1[1], r2[1])
            if t == '(':
                advance()
                node = parse_expr()
                if node is None:
                    return None
                if peek() != ')':
                    return None
                advance()
                return ('paren', node)
            return None

        node = parse_expr()
        if node is None:
            return None
        if pos != len(tokens):
            return None
        return node

    def expand_sum(a, b):
        col1 = ord(a[0]) - ord('A')
        row1 = int(a[1:])
        col2 = ord(b[0]) - ord('A')
        row2 = int(b[1:])
        c1, c2 = (col1, col2) if col1 < col2 else (col2, col1)
        r1, r2 = (row1, row2) if row1 < row2 else (row2, row1)
        out = []
        for row in range(r1, r2 + 1):
            for col in range(c1, c2 + 1):
                out.append(chr(ord('A') + col) + str(row))
        return out

    def refs_of(node):
        kind = node[0]
        if kind == 'int':
            return []
        if kind == 'ref':
            return [node[1]]
        if kind == 'sum':
            return expand_sum(node[1], node[2])
        if kind == 'neg':
            return refs_of(node[1])
        if kind == 'paren':
            return refs_of(node[1])
        if kind == 'bin':
            return refs_of(node[2]) + refs_of(node[3])
        return []

    literal = {}
    formula_text = {}
    for name, raw in cells.items():
        if raw.startswith('='):
            formula_text[name] = raw[1:]
        else:
            literal[name] = parse_literal(raw)

    formula_ast = {}
    syntax_error = set()
    for name, text in formula_text.items():
        ast = parse_formula(text)
        if ast is None:
            syntax_error.add(name)
        else:
            formula_ast[name] = ast

    adjacency = {}
    for name, ast in formula_ast.items():
        adjacency[name] = refs_of(ast)

    def reaches_self(start):
        visited = set()
        stack = list(adjacency.get(start, ()))
        while stack:
            cur = stack.pop()
            if cur == start:
                return True
            if cur in visited:
                continue
            visited.add(cur)
            for nb in adjacency.get(cur, ()):
                if nb not in visited:
                    stack.append(nb)
        return False

    cycle = set()
    for name in formula_ast:
        if reaches_self(name):
            cycle.add(name)

    values = {}

    def get_value(name):
        if name in values:
            return values[name]
        if name in literal:
            v = literal[name]
            values[name] = v
            return v
        if name in syntax_error:
            values[name] = '#SYNTAX'
            return '#SYNTAX'
        if name in cycle:
            values[name] = '#CYCLE'
            return '#CYCLE'
        ast = formula_ast.get(name)
        if ast is None:
            values[name] = 0
            return 0
        refs = refs_of(ast)
        ref_values = [get_value(r) for r in refs]
        for v in ref_values:
            if isinstance(v, str):
                values[name] = v
                return v

        def eval_node(node):
            kind = node[0]
            if kind == 'int':
                return node[1]
            if kind == 'ref':
                return get_value(node[1])
            if kind == 'sum':
                total = 0
                for r in expand_sum(node[1], node[2]):
                    total += get_value(r)
                return total
            if kind == 'neg':
                return -eval_node(node[1])
            if kind == 'paren':
                return eval_node(node[1])
            if kind == 'bin':
                l = eval_node(node[2])
                r = eval_node(node[3])
                op = node[1]
                if op == '+':
                    return l + r
                if op == '-':
                    return l - r
                if op == '*':
                    return l * r
            raise AssertionError('unknown node')

        v = eval_node(ast)
        values[name] = v
        return v

    result = {}
    for name in cells:
        result[name] = get_value(name)
    return result

def spreadsheet_eval(cells):
    def is_digit(ch):
        return '0' <= ch <= '9'

    def is_ref(tok):
        if len(tok) < 2:
            return False
        if not ('A' <= tok[0] <= 'Z'):
            return False
        row = tok[1:]
        if len(row) == 1:
            return '1' <= row[0] <= '9'
        if len(row) == 2:
            return '1' <= row[0] <= '9' and is_digit(row[1])
        return False

    def tokenize(text):
        tokens = []
        i = 0
        n = len(text)
        while i < n:
            c = text[i]
            if c == ' ':
                i += 1
                continue
            if text.startswith('SUM(', i):
                tokens.append('SUM(')
                i += 4
                continue
            if c in '+-*:()':
                tokens.append(c)
                i += 1
                continue
            if is_digit(c):
                j = i + 1
                while j < n and is_digit(text[j]):
                    j += 1
                tokens.append(text[i:j])
                i = j
                continue
            if 'A' <= c <= 'Z':
                j = i + 1
                if j < n and is_digit(text[j]):
                    k = j
                    while k < n and is_digit(text[k]):
                        k += 1
                    ref = text[i:k]
                    if not is_ref(ref):
                        raise SyntaxError('invalid REF')
                    tokens.append(ref)
                    i = k
                    continue
                raise SyntaxError('invalid REF')
            raise SyntaxError('invalid token')
        return tokens

    def parse_formula(text):
        try:
            tokens = tokenize(text)
        except SyntaxError:
            return None
        pos = 0

        def peek():
            return tokens[pos] if pos < len(tokens) else None

        def parse_expr():
            nonlocal pos
            left = parse_term()
            while pos < len(tokens) and tokens[pos] in ('+', '-'):
                op = tokens[pos]
                pos += 1
                right = parse_term()
                left = ('binop', op, left, right)
            return left

        def parse_term():
            nonlocal pos
            left = parse_unary()
            while pos < len(tokens) and tokens[pos] == '*':
                pos += 1
                right = parse_unary()
                left = ('binop', '*', left, right)
            return left

        def parse_unary():
            nonlocal pos
            if pos < len(tokens) and tokens[pos] == '-':
                pos += 1
                val = parse_unary()
                return ('neg', val)
            return parse_primary()

        def parse_primary():
            nonlocal pos
            tok = peek()
            if tok is None:
                raise SyntaxError('unexpected end')
            if tok.isdigit():
                pos += 1
                return ('num', int(tok))
            if is_ref(tok):
                pos += 1
                return ('ref', tok)
            if tok == 'SUM(':
                pos += 1
                ref1 = peek()
                if not is_ref(ref1):
                    raise SyntaxError('expected REF')
                pos += 1
                if peek() != ':':
                    raise SyntaxError('expected :')
                pos += 1
                ref2 = peek()
                if not is_ref(ref2):
                    raise SyntaxError('expected REF')
                pos += 1
                if peek() != ')':
                    raise SyntaxError('expected )')
                pos += 1
                return ('sum', ref1, ref2)
            if tok == '(':
                pos += 1
                val = parse_expr()
                if peek() != ')':
                    raise SyntaxError('expected )')
                pos += 1
                return val
            raise SyntaxError('unexpected token')

        try:
            ast = parse_expr()
            if pos != len(tokens):
                raise SyntaxError('trailing tokens')
            return ast
        except SyntaxError:
            return None

    def expand_refs(a, b):
        c1 = ord(a[0]) - ord('A')
        r1 = int(a[1:])
        c2 = ord(b[0]) - ord('A')
        r2 = int(b[1:])
        cmin = min(c1, c2)
        cmax = max(c1, c2)
        rmin = min(r1, r2)
        rmax = max(r1, r2)
        out = []
        for r in range(rmin, rmax + 1):
            for c in range(cmin, cmax + 1):
                out.append(chr(ord('A') + c) + str(r))
        return out

    def collect_refs(node):
        kind = node[0]
        if kind == 'num':
            return []
        if kind == 'ref':
            return [node[1]]
        if kind == 'sum':
            return expand_refs(node[1], node[2])
        if kind == 'neg':
            return collect_refs(node[1])
        if kind == 'binop':
            return collect_refs(node[2]) + collect_refs(node[3])
        raise AssertionError('bad node')

    def eval_ast(node, values):
        kind = node[0]
        if kind == 'num':
            return node[1]
        if kind == 'ref':
            return values.get(node[1], 0)
        if kind == 'sum':
            total = 0
            for ref in expand_refs(node[1], node[2]):
                total += values.get(ref, 0)
            return total
        if kind == 'neg':
            return -eval_ast(node[1], values)
        if kind == 'binop':
            left = eval_ast(node[2], values)
            right = eval_ast(node[3], values)
            if node[1] == '+':
                return left + right
            if node[1] == '-':
                return left - right
            if node[1] == '*':
                return left * right
        raise AssertionError('bad node')

    def is_int_literal(raw):
        if not isinstance(raw, str) or raw == '':
            return False
        i = 0
        if raw[0] == '-':
            i = 1
            if i == len(raw):
                return False
        while i < len(raw):
            if not is_digit(raw[i]):
                return False
            i += 1
        return True

    values = {}
    asts = {}
    refs = {}

    for name, raw in cells.items():
        if isinstance(raw, str) and raw.startswith('='):
            ast = parse_formula(raw[1:])
            if ast is None:
                values[name] = '#SYNTAX'
            else:
                asts[name] = ast
                refs[name] = collect_refs(ast)
        else:
            if is_int_literal(raw):
                values[name] = int(raw)
            else:
                values[name] = '#VALUE'

    cycle_set = set()
    for start in list(asts):
        seen = {start}
        stack = [start]
        found = False
        while stack and not found:
            cur = stack.pop()
            for ref in refs.get(cur, ()):
                if ref == start:
                    found = True
                    break
                if ref not in seen:
                    seen.add(ref)
                    stack.append(ref)
        if found:
            cycle_set.add(start)

    for name in cycle_set:
        values[name] = '#CYCLE'

    noncycle = [name for name in asts if name not in cycle_set]
    noncycle_set = set(noncycle)
    indegree = {}
    reverse_adj = {}

    for name in noncycle:
        deps = set(refs[name]) & noncycle_set
        indegree[name] = len(deps)
        for dep in deps:
            reverse_adj.setdefault(dep, set()).add(name)

    queue = [name for name in noncycle if indegree[name] == 0]
    qi = 0
    while qi < len(queue):
        name = queue[qi]
        qi += 1
        first_error = None
        for ref in refs[name]:
            v = values.get(ref, 0)
            if isinstance(v, str):
                first_error = v
                break
        if first_error is not None:
            values[name] = first_error
        else:
            values[name] = eval_ast(asts[name], values)
        for dep in reverse_adj.get(name, ()):
            indegree[dep] -= 1
            if indegree[dep] == 0:
                queue.append(dep)

    return {name: values[name] for name in cells}

