def common_free_slots(calendars, day_start, day_end, min_len):
    if min_len < 1:
        return None

    def parse_time(t):
        if not isinstance(t, str) or len(t) != 5 or t[2] != ':':
            return None
        hh = t[:2]
        mm = t[3:]
        for ch in hh + mm:
            if ch < '0' or ch > '9':
                return None
        h = int(hh)
        m = int(mm)
        if h == 24:
            return 1440 if m == 0 else None
        if h > 23 or m > 59:
            return None
        return h * 60 + m

