    for cal in calendars:
        offset, busy = cal
        for s, e in busy:
            sm = parse_time(s)
            em = parse_time(e)
            if sm is None or em is None:
                return None
            busy_intervals.append((offset, sm, em))

    if de <= ds:
        return []

