        if em <= sm:
            continue
        a = sm - offset
        b = em - offset
        if a < ds:
            a = ds
        if b > de:
            b = de
        if b > a:
            intervals.append((a, b))

    intervals.sort(key=lambda iv: iv[0])
    merged = []
    for a, b in intervals:
        if merged and a <= merged[-1][1]:
            if b > merged[-1][1]:
                merged[-1][1] = b
        else:
            merged.append([a, b])

    slots = []
    cur = ds
    for a, b in merged:
        if a > cur:
            if a - cur >= min_len:
                slots.append([fmt(cur), fmt(a)])
        if b > cur:
            cur = b
    if de > cur and de - cur >= min_len:
        slots.append([fmt(cur), fmt(de)])
    return slots

