    for entry in calendars:
        offset = entry[0]
        for interval in entry[1]:
            s = parse_time(interval[0])
            e = parse_time(interval[1])
            if s is None or e is None:
                return None
            if e <= s:
                continue
            s -= offset
            e -= offset
            s = max(s, start)
            e = min(e, end)
            if s < e:
                intervals.append((s, e))

