    cursor = start
    for s, e in merged:
        if s > cursor and s - cursor >= min_len:
            free.append((cursor, s))
        if e > cursor:
            cursor = e
    if end > cursor and end - cursor >= min_len:
        free.append((cursor, end))

    return [[fmt(s), fmt(e)] for s, e in free]

