    # Empty dict is the zero polynomial.

    def is_digit(tok):
        return '0' <= tok[0] <= '9'

    def add(a, b):
        r = dict(a)
        for d, c in b.items():
            nv = r.get(d, 0) + c
            if nv:
                r[d] = nv
            else:
                r.pop(d, None)
        return r

