        if not a or not b:
            return {}
        r = {}
        for d1, c1 in a.items():
            for d2, c2 in b.items():
                d = d1 + d2
                nv = r.get(d, 0) + c1 * c2
                if nv:
                    r[d] = nv
                else:
                    r.pop(d, None)
        return r

    def pow_poly(a, e):
        if e == 0:
            return {0: 1}
        r = {0: 1}
        base = a
        while e:
            if e & 1:
                r = mul(r, base)
            e >>= 1
            if e:
                base = mul(base, base)
        return r

    def binop(a, op, b):
        if op == '+':
            return add(a, b)
        if op == '-':
            return add(a, neg(b))
        return mul(a, b)

    def prec_of(op):
        if op == 'neg':
            return 3
        if op == '*':
            return 2
        return 1

    def apply_op(vals, op):
        if op == 'neg':
            if not vals:
                return None
            v = vals.pop()
            nv = neg(v)
            vals.append(nv)
            return vals
        if len(vals) < 2:
            return None
        b = vals.pop()
        a = vals.pop()
        vals.append(binop(a, op, b))
        return vals

    # Shunting-yard style evaluation with an explicit stack.
    ops = []
    vals = []
    paren_marks = []
    pos = 0
    m = len(tokens)

    while pos < m:
        tok = tokens[pos]
