            while ops and ops[-1] != '(' and prec_of(ops[-1]) >= prec:
                op = ops.pop()
                vals = apply_op(vals, op)
                if vals is None:
                    return None
            ops.append('*')
            pos += 1
            continue
        if tok == 'x':
            vals.append({1: 1})
            pos += 1
            continue
        if is_digit(tok):
            v = int(tok)
            vals.append({0: v} if v else {})
            pos += 1
            continue
        return None

    while ops:
        op = ops.pop()
        if op == '(':
            return None
        vals = apply_op(vals, op)
        if vals is None:
            return None
    if len(vals) != 1:
        return None
    p = vals[0]

    if not p:
        return '0'
    out = []
    first = True
    for d in sorted(p, reverse=True):
        c = p[d]
        mag = abs(c)
        if d == 0:
            body = str(mag)
