def json_select(doc, path):
    if not isinstance(path, str):
        return None
    n = len(path)
    if n == 0 or path[0] != '$':
        return None

    def _name_at(i):
        if i >= n:
            return None, i
        c = path[i]
        if not ('A' <= c <= 'Z' or 'a' <= c <= 'z' or c == '_'):
            return None, i
        j = i + 1
        while j < n:
            ch = path[j]
            if 'A' <= ch <= 'Z' or 'a' <= ch <= 'z' or '0' <= ch <= '9' or ch == '_':
                j += 1
            else:
                break
        return path[i:j], j

    steps = []
    i = 1
    while i < n:
        c = path[i]
        if c == '.':
            if path.startswith('..', i):
                name, j = _name_at(i + 2)
                if name is None:
                    return None
                steps.append(('recurse', name))
                i = j
            else:
                name, j = _name_at(i + 1)
                if name is None:
                    return None
                steps.append(('key', name))
                i = j
        elif c == '[':
            if path.startswith("['", i):
                j = i + 2
                chars = []
                while True:
                    if j >= n:
                        return None
                    ch = path[j]
                    if ch == '\\':
                        if j + 1 >= n:
                            return None
                        nxt = path[j + 1]
                        if nxt == "'":
                            chars.append("'")
                            j += 2
                        elif nxt == '\\':
                            chars.append('\\')
                            j += 2
                        else:
                            return None
                    elif ch == "'":
                        break
                    else:
                        chars.append(ch)
                        j += 1
                if j + 1 >= n or path[j + 1] != ']':
                    return None
                steps.append(('key', ''.join(chars)))
                i = j + 2
            elif path.startswith('[*]', i):
                steps.append(('star',))
                i += 3
            else:
                j = i + 1
                neg = False
                if j < n and path[j] == '-':
                    neg = True
                    j += 1
                dstart = j
                while j < n and '0' <= path[j] <= '9':
                    j += 1
                digits = path[dstart:j]
                if digits == '':
                    return None
                if len(digits) > 1 and digits[0] == '0':
                    return None
                if j >= n or path[j] != ']':
                    return None
                try:
                    num = int(digits)
                except ValueError:
                    num = None
                if num is not None and neg:
                    num = -num
                steps.append(('index', num))
                i = j + 1
        else:
            return None

    def _collect(value, name, out):
        stack = [value]
        while stack:
            node = stack.pop()
            if isinstance(node, dict):
                if name in node:
                    out.append(node[name])
                for key in reversed(list(node)):
                    stack.append(node[key])
            elif isinstance(node, list):
                for item in reversed(node):
                    stack.append(item)

    current = [doc]
    for step in steps:
        kind = step[0]
        if kind == 'key':
            name = step[1]
            new = []
            for v in current:
                if isinstance(v, dict) and name in v:
                    new.append(v[name])
            current = new
        elif kind == 'index':
            num = step[1]
            new = []
            if num is not None:
                for v in current:
                    if isinstance(v, list):
                        idx = num if num >= 0 else len(v) + num
                        if 0 <= idx < len(v):
                            new.append(v[idx])
            current = new
        elif kind == 'star':
            new = []
            for v in current:
                if isinstance(v, list):
                    new.extend(v)
                elif isinstance(v, dict):
                    new.extend(v.values())
            current = new
        else:  # recurse
            name = step[1]
            new = []
            for v in current:
                _collect(v, name, new)
            current = new
    return current

