        while pos < n and expr[pos] == ' ':
            pos += 1

    def negate(p):
        return {d: -c for d, c in p.items()}

    def add(a, b):
        r = dict(a)
        for d, c in b.items():
            nc = r.get(d, 0) + c
            if nc == 0:
                r.pop(d, None)
            else:
                r[d] = nc
        return r

    def multiply(a, b):
        if not a or not b:
            return {}
        r = {}
