        nonlocal pos
        skip_ws()
        start = pos
        while pos < n and '0' <= expr[pos] <= '9':
            pos += 1
        if pos == start:
            raise _ParseError()
        return int(expr[start:pos])

    def parse_base():
        nonlocal pos
        skip_ws()
        if pos >= n:
            raise _ParseError()
        ch = expr[pos]
        if '0' <= ch <= '9':
