    def parse_term():
        nonlocal pos
        p = parse_factor()
        while True:
            skip_ws()
            if pos < n and expr[pos] == '*':
                pos += 1
                p = multiply(p, parse_factor())
            else:
                return p

    def parse_expr():
        nonlocal pos
        p = parse_term()
