                pos += 1
                p = add(p, parse_term())
            elif pos < n and expr[pos] == '-':
                pos += 1
                p = add(p, negate(parse_term()))
            else:
                return p

    def format_poly(p):
        if not p:
            return '0'
        parts = []
        for i, (d, c) in enumerate(sorted(p.items(), key=lambda kv: -kv[0])):
            ac = abs(c)
            if d == 0:
                s = str(ac)
            else:
                s = ('' if ac == 1 else str(ac)) + 'x'
                if d > 1:
                    s += '^' + str(d)
