                if c < 0:
                    s = '-' + s
                parts.append(s)
            else:
                parts.append(('+' if c > 0 else '-') + s)
        return ''.join(parts)

    try:
        p = parse_expr()
        skip_ws()
        if pos != n:
            return None
        return format_poly(p)
    except _ParseError:
        return None

