    stack = [name for name in noncycle_nodes if remaining[name] == 0]
    while stack:
        name = stack.pop()
        refs = parsed_refs[name]
        err = None
        for r in refs:
            v = value_of(r)
            if isinstance(v, str):
                err = v
                break
