            j = i + 1
            if j >= len(tokens) or tokens[j][0] != 'ref':
                raise SyntaxError('expected reference')
            a = tokens[j][1]
            j += 1
            if j >= len(tokens) or tokens[j][0] != ':':
                raise SyntaxError('expected colon')
            j += 1
            if j >= len(tokens) or tokens[j][0] != 'ref':
                raise SyntaxError('expected reference')
            b = tokens[j][1]
            j += 1
            if j >= len(tokens) or tokens[j][0] != ')':
                raise SyntaxError('expected closing paren')
            j += 1
            return ('sum', a, b), j
        if tok[0] == '(':
            node, j = parse_expr(tokens, i + 1)
            if j >= len(tokens) or tokens[j][0] != ')':
                raise SyntaxError('expected closing paren')
            return node, j + 1
        raise SyntaxError('bad primary')

    def parse_unary(tokens, i):
        neg = 0
        while i < len(tokens) and tokens[i][0] == '-':
            neg += 1
            i += 1
        node, i = parse_primary(tokens, i)
        while neg:
            node = ('neg', node)
            neg -= 1
        return node, i

    def parse_term(tokens, i):
        node, i = parse_unary(tokens, i)
        while i < len(tokens) and tokens[i][0] == '*':
            rhs, i = parse_unary(tokens, i + 1)
            node = ('*', node, rhs)
        return node, i

    def parse_expr(tokens, i):
        node, i = parse_term(tokens, i)
