    refs_map = {k: collect_refs(node) for k, node in parsed.items()}

    cyclic = set()
    for k in parsed:
        seen = set()
        stack = list(refs_map[k])
        while stack:
            r = stack.pop()
            if r == k:
                cyclic.add(k)
                break
            if r in parsed and r not in seen:
                seen.add(r)
                stack.extend(refs_map[r])

