                return left - right
            return left * right
        raise AssertionError('unknown node')

    def parse_formula(formula):
        s = formula
        n = len(s)

        def skip_spaces(i):
            while i < n and s[i] == ' ':
                i += 1
            return i

        def parse_ref_name(i):
            i = skip_spaces(i)
            if i >= n or not ('A' <= s[i] <= 'Z'):
                raise SyntaxError('expected REF')
            letter = s[i]
            i += 1
            start = i
            while i < n and '0' <= s[i] <= '9':
                i += 1
            digits = s[start:i]
            if not digits:
                raise SyntaxError('expected row')
            row = int(digits)
            if row < 1 or row > 99:
                raise SyntaxError('bad row')
            if digits != str(row):
                raise SyntaxError('bad row')
            return letter + digits, i

        def parse_primary(i):
            i = skip_spaces(i)
            if i >= n:
                raise SyntaxError('unexpected end')
            ch = s[i]
            if ch == '(':
                i += 1
                node, refs, i = parse_expr(i)
                i = skip_spaces(i)
                if i >= n or s[i] != ')':
                    raise SyntaxError('expected )')
                i += 1
                return node, refs, i
            if '0' <= ch <= '9':
                start = i
                while i < n and '0' <= s[i] <= '9':
                    i += 1
                digits = s[start:i]
                return ('int', int(digits)), [], i
            if ch == 'S' and s.startswith('SUM(', i):
                i += 4
                ref1, i = parse_ref_name(i)
                i = skip_spaces(i)
                if i >= n or s[i] != ':':
                    raise SyntaxError('expected :')
                i += 1
                ref2, i = parse_ref_name(i)
                i = skip_spaces(i)
                if i >= n or s[i] != ')':
                    raise SyntaxError('expected )')
                i += 1
                return ('sum', ref1, ref2), expand(ref1, ref2), i
            if 'A' <= ch <= 'Z':
                name, i = parse_ref_name(i)
                return ('ref', name), [name], i
            raise SyntaxError('unexpected token')

        def parse_unary(i):
            i = skip_spaces(i)
            if i < n and s[i] == '-':
                i += 1
                child, refs, i = parse_unary(i)
                return ('neg', child), refs, i
            return parse_primary(i)

        def parse_term(i):
            left, refs_left, i = parse_unary(i)
            refs = refs_left
            while True:
                i = skip_spaces(i)
                if i < n and s[i] == '*':
                    i += 1
                    right, refs_right, i = parse_unary(i)
                    refs = refs + refs_right
                    left = ('bin', '*', left, right)
                    continue
                break
            return left, refs, i

        def parse_expr(i):
            left, refs_left, i = parse_term(i)
            refs = refs_left
            while True:
                i = skip_spaces(i)
                if i < n and s[i] in '+-':
                    op = s[i]
                    i += 1
                    right, refs_right, i = parse_term(i)
                    refs = refs + refs_right
                    left = ('bin', op, left, right)
                    continue
                break
            return left, refs, i

        node, refs, i = parse_expr(0)
        i = skip_spaces(i)
        if i != n:
            raise SyntaxError('trailing garbage')
        return node, refs

    records = {}
    values = {}
    for key, raw in cells.items():
        if not raw.startswith('='):
            if is_int_literal(raw):
                values[key] = int(raw)
            else:
                values[key] = '#VALUE'
            records[key] = {'kind': 'literal', 'value': values[key]}
        else:
            try:
                ast, refs = parse_formula(raw[1:])
            except SyntaxError:
                records[key] = {'kind': 'formula', 'parse_error': True}
                values[key] = '#SYNTAX'
            else:
                records[key] = {'kind': 'formula', 'ast': ast, 'refs': refs, 'cycle': False}

    formula_names = [key for key, rec in records.items() if rec['kind'] == 'formula' and 'ast' in rec]
    edges = {key: set() for key in formula_names}
    for key in formula_names:
        for ref in records[key]['refs']:
            if ref in edges:
                edges[key].add(ref)

    def reaches_self(start):
        seen = {start}
        stack = [start]
        while stack:
            node = stack.pop()
            for nxt in edges.get(node, ()):
                if nxt == start:
                    return True
                if nxt not in seen:
                    seen.add(nxt)
                    stack.append(nxt)
        return False

    cycle_names = set()
    for key in formula_names:
        if reaches_self(key):
            cycle_names.add(key)

    for key in cycle_names:
        records[key]['cycle'] = True
        values[key] = '#CYCLE'

    memo = {}

    def ref_value(ref):
        if ref in memo:
            return memo[ref]
        rec = records.get(ref)
        if rec is None:
            return 0
        if rec['kind'] == 'literal':
            return rec['value']
        if 'ast' not in rec:
            return '#SYNTAX'
        if rec.get('cycle'):
            return '#CYCLE'
        value = compute_formula(ref)
        memo[ref] = value
        return value

    def compute_formula(key):
        rec = records[key]
        for ref in rec['refs']:
            value = ref_value(ref)
            if isinstance(value, str):
                return value
        return eval_node(rec['ast'], ref_value)

    for key in formula_names:
        if key not in cycle_names:
            value = compute_formula(key)
            memo[key] = value
            values[key] = value

    return values

import re

def spreadsheet_eval(cells):
    REF_RE = re.compile(r'[A-Z][1-9][0-9]?')

    def tokenize(s):
        tokens = []
        i = 0
        n = len(s)
        while i < n:
            c = s[i]
            if c == ' ':
                i += 1
                continue
            if '0' <= c <= '9':
                j = i
                while j < n and '0' <= s[j] <= '9':
                    j += 1
                tokens.append(('num', int(s[i:j])))
                i = j
                continue
            if c in '+-*:()':
                tokens.append((c, c))
                i += 1
                continue
            if c == 'S' and s.startswith('SUM(', i):
                tokens.append(('SUM(',))
                i += 4
                continue
            if 'A' <= c <= 'Z':
                m = REF_RE.match(s, i)
                if m:
                    tokens.append(('ref', m.group()))
                    i = m.end()
                    continue
                raise SyntaxError('bad REF')
            raise SyntaxError('bad char')
        return tokens

    def parse(tokens):
        pos = 0

        def parse_ref_token():
            nonlocal pos
            if pos >= len(tokens) or tokens[pos][0] != 'ref':
                raise SyntaxError('expected REF')
            name = tokens[pos][1]
            pos += 1
            return name

        def parse_primary():
            nonlocal pos
            if pos >= len(tokens):
                raise SyntaxError('unexpected end')
            tok = tokens[pos]
            if tok[0] == 'SUM(':
                pos += 1
                a = parse_ref_token()
                if pos >= len(tokens) or tokens[pos][0] != ':':
                    raise SyntaxError('expected :')
                pos += 1
                b = parse_ref_token()
                if pos >= len(tokens) or tokens[pos][0] != ')':
                    raise SyntaxError('expected )')
                pos += 1
                return ('sum', a, b)
            if tok[0] == '(':
                pos += 1
                node = parse_expr()
                if pos >= len(tokens) or tokens[pos][0] != ')':
                    raise SyntaxError('expected )')
                pos += 1
                return node
            if tok[0] == 'num':
                pos += 1
                return ('num', tok[1])
            if tok[0] == 'ref':
                pos += 1
                return ('ref', tok[1])
            raise SyntaxError('bad primary')

        def parse_unary():
            nonlocal pos
            if pos < len(tokens) and tokens[pos][0] == '-':
                pos += 1
                return ('neg', parse_unary())
            return parse_primary()

        def parse_term():
            nonlocal pos
            node = parse_unary()
            while pos < len(tokens) and tokens[pos][0] == '*':
                pos += 1
                rhs = parse_unary()
                node = ('bin', '*', node, rhs)
            return node

        def parse_expr():
            nonlocal pos
            node = parse_term()
            while pos < len(tokens) and tokens[pos][0] in ('+', '-'):
                op = tokens[pos][0]
                pos += 1
                rhs = parse_term()
                node = ('bin', op, node, rhs)
            return node

        node = parse_expr()
        if pos != len(tokens):
            raise SyntaxError('trailing tokens')
        return node

    def expand(a, b):
        col_a = ord(a[0]) - 65
        row_a = int(a[1:])
        col_b = ord(b[0]) - 65
        row_b = int(b[1:])
        top = min(row_a, row_b)
        bottom = max(row_a, row_b)
        left = min(col_a, col_b)
        right = max(col_a, col_b)
        out = []
        for r in range(top, bottom + 1):
            for c in range(left, right + 1):
                out.append(chr(65 + c) + str(r))
        return out

    def extract_refs(node):
        kind = node[0]
        if kind == 'ref':
            return [node[1]]
        if kind == 'sum':
            return expand(node[1], node[2])
        if kind == 'num':
            return []
        if kind == 'neg':
            return extract_refs(node[1])
        if kind == 'bin':
            return extract_refs(node[2]) + extract_refs(node[3])
        return []

    asts = {}
    refs = {}
    for name, raw in cells.items():
        if raw.startswith('='):
            try:
                ast = parse(tokenize(raw[1:]))
            except SyntaxError:
                continue
            asts[name] = ast
            refs[name] = extract_refs(ast)

    cycle_cells = set()
    for name in refs:
        seen = set()
        stack = list(refs[name])
        while stack:
            node = stack.pop()
            if node == name:
                cycle_cells.add(name)
                break
            if node in seen:
                continue
            seen.add(node)
            if node in refs:
                stack.extend(refs[node])

    values = {}

    def evaluate(node):
        kind = node[0]
        if kind == 'num':
            return node[1]
        if kind == 'ref':
            return get_value(node[1])
        if kind == 'sum':
            total = 0
            for cell in expand(node[1], node[2]):
                total += get_value(cell)
            return total
        if kind == 'neg':
            return -evaluate(node[1])
        if kind == 'bin':
            op = node[1]
            left = evaluate(node[2])
            right = evaluate(node[3])
            if op == '+':
                return left + right
            if op == '-':
                return left - right
            return left * right
        raise SyntaxError('bad node')

    def get_value(name):
        if name in values:
            return values[name]
        if name not in cells:
            return 0
        raw = cells[name]
        if not raw.startswith('='):
            if re.fullmatch(r'-?[0-9]+', raw):
                values[name] = int(raw)
            else:
                values[name] = '#VALUE'
            return values[name]
        if name in cycle_cells:
            values[name] = '#CYCLE'
            return values[name]
        if name not in asts:
            values[name] = '#SYNTAX'
            return values[name]
        for ref in refs[name]:
            v = get_value(ref)
            if isinstance(v, str):
                values[name] = v
                return values[name]
        values[name] = evaluate(asts[name])
        return values[name]

    for name in cells:
        get_value(name)

    return {name: values[name] for name in cells}

import re


_REF_PREFIX = re.compile(r'[A-Z](?:[1-9][0-9]|[1-9])')
_REF_FULL = re.compile(r'[A-Z](?:[1-9][0-9]|[1-9])')
_INT_FULL = re.compile(r'[0-9]+')


def _tokenize(s):
    tokens = []
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c == ' ':
            i += 1
            continue
        if s.startswith('SUM(', i):
            tokens.append('SUM(')
            i += 4
            continue
        if c in '+-*():':
            tokens.append(c)
            i += 1
            continue
        if '0' <= c <= '9':
            j = i
            while j < n and '0' <= s[j] <= '9':
                j += 1
            tokens.append(s[i:j])
            i = j
            continue
        if 'A' <= c <= 'Z':
            m = _REF_PREFIX.match(s, i)
            if m is not None:
                tokens.append(m.group())
                i = m.end()
                continue
            raise ValueError('invalid reference')
        raise ValueError('invalid character')
    return tokens


class _Parser:
    __slots__ = ('tokens', 'pos')

    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def next(self):
        t = self.tokens[self.pos]
        self.pos += 1
        return t

    def parse_expr(self):
        node = self.parse_term()
        while self.peek() == '+' or self.peek() == '-':
            op = self.next()
            right = self.parse_term()
            node = ('binop', op, node, right)
        return node

    def parse_term(self):
        node = self.parse_unary()
        while self.peek() == '*':
            self.next()
            right = self.parse_unary()
            node = ('binop', '*', node, right)
        return node

    def parse_unary(self):
        if self.peek() == '-':
            self.next()
            return ('neg', self.parse_unary())
        return self.parse_primary()

    def parse_primary(self):
        t = self.next()
        if t == '(':
            node = self.parse_expr()
            if self.next() != ')':
                raise ValueError('expected )')
            return node
        if t == 'SUM(':
            r1 = self.next()
            if not _REF_FULL.fullmatch(r1):
                raise ValueError('bad ref')
            if self.next() != ':':
                raise ValueError('expected :')
            r2 = self.next()
            if not _REF_FULL.fullmatch(r2):
                raise ValueError('bad ref')
            if self.next() != ')':
                raise ValueError('expected )')
            return ('sum', r1, r2)
        if _REF_FULL.fullmatch(t):
            return ('ref', t)
        if _INT_FULL.fullmatch(t):
            return ('int', int(t))
        raise ValueError('bad primary')


def _parse_formula(s):
    try:
        tokens = _tokenize(s)
        parser = _Parser(tokens)
        node = parser.parse_expr()
        if parser.peek() is not None:
            return None
        return node
    except Exception:
        return None


def _sum_refs(r1, r2):
    col1 = ord(r1[0]) - 65
    row1 = int(r1[1:])
    col2 = ord(r2[0]) - 65
    row2 = int(r2[1:])
    refs = []
    for row in range(min(row1, row2), max(row1, row2) + 1):
        for col in range(min(col1, col2), max(col1, col2) + 1):
            refs.append(chr(65 + col) + str(row))
    return refs


def _refs_of(node):
    t = node[0]
    if t == 'int':
        return []
    if t == 'ref':
        return [node[1]]
    if t == 'neg':
        return _refs_of(node[1])
    if t == 'binop':
        return _refs_of(node[2]) + _refs_of(node[3])
    return _sum_refs(node[1], node[2])


def _eval_ast(node, cell_value):
    t = node[0]
    if t == 'int':
        return node[1]
    if t == 'ref':
        return cell_value(node[1])
    if t == 'neg':
        return -_eval_ast(node[1], cell_value)
    if t == 'binop':
        left = _eval_ast(node[2], cell_value)
        right = _eval_ast(node[3], cell_value)
        op = node[1]
        if op == '+':
            return left + right
        if op == '-':
            return left - right
        return left * right
    total = 0
    for r in _sum_refs(node[1], node[2]):
        total += cell_value(r)
    return total


def _reaches_self(start, refs_map, formula_keys):
    stack = [r for r in refs_map[start] if r in formula_keys]
    seen = set()
    while stack:
        node = stack.pop()
        if node == start:
            return True
        if node in seen:
            continue
        seen.add(node)
        for r in refs_map[node]:
            if r in formula_keys:
                stack.append(r)
    return False


def spreadsheet_eval(cells):
    literal_values = {}
    formulas = {}
    for key, raw in cells.items():
        if not isinstance(raw, str):
            literal_values[key] = '#VALUE'
            continue
        if not raw.startswith('='):
            if re.fullmatch(r'-?[0-9]+', raw):
                literal_values[key] = int(raw)
            else:
                literal_values[key] = '#VALUE'
            continue
        ast = _parse_formula(raw[1:])
        if ast is None:
            literal_values[key] = '#SYNTAX'
        else:
            formulas[key] = ast

    refs_map = {}
    for key, ast in formulas.items():
        refs_map[key] = _refs_of(ast)

    formula_keys = set(formulas)
    cycle = set()
    for key in formulas:
        if _reaches_self(key, refs_map, formula_keys):
            cycle.add(key)

    values = dict(literal_values)
    for key in formulas:
        if key in cycle:
            values[key] = '#CYCLE'

    def cell_value(name):
        v = values.get(name)
        if v is not None:
            return v
        if name not in cells:
            return 0
        ast = formulas[name]
        for r in refs_map[name]:
            rv = cell_value(r)
            if isinstance(rv, str):
                values[name] = rv
                return rv
        v = _eval_ast(ast, cell_value)
        values[name] = v
        return v

    for key in formulas:
        if key not in cycle:
            cell_value(key)

    return {key: values[key] for key in cells}

