            tok = peek()
            if tok is None:
                return v
            if tok[0] == '*':
                advance()
                rhs = parse_unary()
                v = v * rhs
            elif tok[0] == '/':
                advance()
                rhs = parse_unary()
                if rhs == 0:
                    raise ValueError('division by zero')
                v = v / rhs
            else:
                return v

