        return ('day', neg, n)
    if head == 'nth':
        if len(parts) != 3:
            return None
        s = parts[1]
        wd = parts[2]
        neg = False
        if s.startswith('-'):
            neg = True
            s = s[1:]
        k = _parse_number(s)
        if k is None or k < 1 or k > 5:
            return None
        if wd not in _WD_INDEX:
            return None
        return ('nth', neg, k, wd)
    return None


