import re

_NAME_RE = re.compile(r'[A-Za-z_][A-Za-z0-9_]*')


def _parse_steps(path):
    if not isinstance(path, str) or not path.startswith('$'):
        return None
    n = len(path)
    pos = 1
    steps = []
    while pos < n:
        c = path[pos]
        if c == '.':
            if path.startswith('..', pos):
                m = _NAME_RE.match(path, pos + 2)
                if m is None:
                    return None
                steps.append(('r', m.group(0)))
                pos = m.end()
            else:
                m = _NAME_RE.match(path, pos + 1)
                if m is None:
                    return None
                steps.append(('k', m.group(0)))
                pos = m.end()
        elif c == '[':
            if path.startswith("['", pos):
                j = pos + 2
                key_chars = []
                while True:
                    if j >= n:
                        return None
                    ch = path[j]
                    if ch == '\\':
                        if j + 1 >= n:
                            return None
                        nxt = path[j + 1]
                        if nxt == "'":
                            key_chars.append("'")
                            j += 2
                        elif nxt == '\\':
                            key_chars.append('\\')
                            j += 2
                        else:
                            return None
                    elif ch == "'":
                        if j + 1 >= n or path[j + 1] != ']':
                            return None
                        steps.append(('k', ''.join(key_chars)))
                        pos = j + 2
                        break
                    else:
                        key_chars.append(ch)
                        j += 1
            elif path.startswith('[*]', pos):
                steps.append(('s',))
                pos += 3
            else:
                j = pos + 1
                neg = False
                if j < n and path[j] == '-':
                    neg = True
                    j += 1
                start = j
                while j < n and '0' <= path[j] <= '9':
                    j += 1
                digits = path[start:j]
                if not digits:
                    return None
                if len(digits) > 1 and digits[0] == '0':
                    return None
                if j >= n or path[j] != ']':
                    return None
                pos = j + 1
                value = int(digits)
                if neg:
                    value = -value
                steps.append(('i', value))
        else:
            return None
    return steps


def _collect_recursive(value, name, out):
    stack = [value]
    while stack:
        v = stack.pop()
        if isinstance(v, dict):
            if name in v:
                out.append(v[name])
            children = list(v.values())
            for i in range(len(children) - 1, -1, -1):
                stack.append(children[i])
        elif isinstance(v, list):
            for i in range(len(v) - 1, -1, -1):
                stack.append(v[i])


