                a = ev(n3[1])
                b = ev(n3[2])
                return (full ^ a) | b
            raise _Reject()

        mask = ev(node)
        minterms = [idx for idx in range(total) if (mask >> idx) & 1]
        return [variables, minterms]
    except _Reject:
        return None

def bool_minterms(expr):
    tokens = []
    i = 0
    m = len(expr)
    while i < m:
        c = expr[i]
        if c == ' ':
            i += 1
            continue
        if 'a' <= c <= 'z':
            j = i + 1
            while j < m and 'a' <= expr[j] <= 'z':
                j += 1
            tokens.append(('v', expr[i:j]))
            i = j
        elif c == '0' or c == '1':
            j = i + 1
            while j < m and (expr[j] == '0' or expr[j] == '1'):
                j += 1
            run = expr[i:j]
            if run == '0':
                tokens.append(('k', 0))
            elif run == '1':
                tokens.append(('k', 1))
            else:
                return None
            i = j
        elif c == '!' or c == '&' or c == '^' or c == '|':
            tokens.append(('o', c))
            i += 1
        elif c == '-':
            if i + 1 < m and expr[i + 1] == '>':
                tokens.append(('o', '->'))
                i += 2
            else:
                return None
        elif c == '(' or c == ')':
            tokens.append(('p', c))
            i += 1
        else:
            return None

    pos = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else None

    def advance():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def parse_expr():
        return parse_implication()

    def parse_implication():
        left = parse_or()
        tok = peek()
        if tok is not None and tok[0] == 'o' and tok[1] == '->':
            advance()
            right = parse_implication()
            return ('->', left, right)
        return left

    def parse_or():
        left = parse_xor()
        while True:
            tok = peek()
            if tok is not None and tok[0] == 'o' and tok[1] == '|':
                advance()
                right = parse_xor()
                left = ('|', left, right)
            else:
                return left

    def parse_xor():
        left = parse_and()
        while True:
            tok = peek()
            if tok is not None and tok[0] == 'o' and tok[1] == '^':
                advance()
                right = parse_and()
                left = ('^', left, right)
            else:
                return left

    def parse_and():
        left = parse_not()
        while True:
            tok = peek()
            if tok is not None and tok[0] == 'o' and tok[1] == '&':
                advance()
                right = parse_not()
                left = ('&', left, right)
            else:
                return left

    def parse_not():
        tok = peek()
        if tok is not None and tok[0] == 'o' and tok[1] == '!':
            advance()
            operand = parse_not()
            return ('!', operand)
        return parse_primary()

    def parse_primary():
        tok = peek()
        if tok is None:
            raise ValueError('unexpected end')
        if tok[0] == 'v':
            advance()
            return ('v', tok[1])
        if tok[0] == 'k':
            advance()
            return ('k', tok[1])
        if tok[0] == 'p' and tok[1] == '(':
            advance()
            node = parse_expr()
            tok2 = peek()
            if tok2 is None or tok2[0] != 'p' or tok2[1] != ')':
                raise ValueError('expected )')
            advance()
            return node
        raise ValueError('unexpected token')

    try:
        tree = parse_expr()
    except ValueError:
        return None
    if pos != len(tokens):
        return None

    variables = set()

    def collect(node):
        kind = node[0]
        if kind == 'v':
            variables.add(node[1])
        elif kind == 'k':
            pass
        elif kind == '!':
            collect(node[1])
        else:
            collect(node[1])
            collect(node[2])

    collect(tree)
    var_list = sorted(variables)

    def evaluate(node, env):
        kind = node[0]
        if kind == 'v':
            return env[node[1]]
        if kind == 'k':
            return bool(node[1])
        if kind == '!':
            return not evaluate(node[1], env)
        if kind == '&':
            return evaluate(node[1], env) and evaluate(node[2], env)
        if kind == '^':
            return evaluate(node[1], env) != evaluate(node[2], env)
        if kind == '|':
            return evaluate(node[1], env) or evaluate(node[2], env)
        if kind == '->':
            return (not evaluate(node[1], env)) or evaluate(node[2], env)
