    n = len(var_list)
    minterms = []
    for i in range(1 << n):
        env = {}
        for j, v in enumerate(var_list):
            env[v] = bool((i >> (n - 1 - j)) & 1)
        if evaluate(tree, env):
            minterms.append(i)
    return [var_list, minterms]

def bool_minterms(expr):
