            continue
        if 'a' <= c <= 'z':
            j = i
            while j < n and 'a' <= expr[j] <= 'z':
                j += 1
            tokens.append(('var', expr[i:j]))
            i = j
            continue
        if c == '!' or c == '&' or c == '^' or c == '|':
            tokens.append(('op', c))
            i += 1
            continue
        if c == '-':
            if i + 1 < n and expr[i + 1] == '>':
                tokens.append(('op', '->'))
                i += 2
                continue
            return None
        if c == '(':
            tokens.append(('lp',))
            i += 1
            continue
        if c == ')':
            tokens.append(('rp',))
            i += 1
            continue
        return None

    pos = 0

    class _Invalid(Exception):
        pass

    def peek():
        return tokens[pos] if pos < len(tokens) else None

    def advance():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def parse_primary():
        tok = peek()
        if tok is None:
            raise _Invalid()
        if tok[0] == 'var':
            advance()
            return ('var', tok[1])
        if tok[0] == 'const':
            advance()
            return ('const', tok[1])
        if tok[0] == 'lp':
            advance()
            node = parse_implication()
            if peek() is not None and peek()[0] == 'rp':
                advance()
                return node
            raise _Invalid()
        raise _Invalid()

    def parse_unary():
        tok = peek()
        if tok is not None and tok[0] == 'op' and tok[1] == '!':
            advance()
            return ('!', parse_unary())
        return parse_primary()

    def parse_and():
        node = parse_unary()
        while True:
            tok = peek()
            if tok is not None and tok[0] == 'op' and tok[1] == '&':
                advance()
                node = ('&', node, parse_unary())
            else:
                return node

    def parse_xor():
        node = parse_and()
        while True:
            tok = peek()
            if tok is not None and tok[0] == 'op' and tok[1] == '^':
                advance()
                node = ('^', node, parse_and())
            else:
                return node

    def parse_or():
        node = parse_xor()
        while True:
            tok = peek()
            if tok is not None and tok[0] == 'op' and tok[1] == '|':
                advance()
                node = ('|', node, parse_xor())
            else:
                return node

    def parse_implication():
        node = parse_or()
        tok = peek()
        if tok is not None and tok[0] == 'op' and tok[1] == '->':
            advance()
            node = ('->', node, parse_implication())
        return node

    try:
        ast = parse_implication()
        if pos != len(tokens):
            raise _Invalid()
    except _Invalid:
        return None

    variables = set()

    def collect(node):
        kind = node[0]
        if kind == 'var':
            variables.add(node[1])
        elif kind == 'const':
            pass
        elif kind == '!':
            collect(node[1])
        else:
            collect(node[1])
            collect(node[2])

    collect(ast)
    var_list = sorted(variables)

    def evaluate(node, values):
        kind = node[0]
        if kind == 'var':
            return values[node[1]]
        if kind == 'const':
            return node[1]
        if kind == '!':
            return not evaluate(node[1], values)
        if kind == '&':
            return evaluate(node[1], values) and evaluate(node[2], values)
        if kind == '^':
            return evaluate(node[1], values) ^ evaluate(node[2], values)
        if kind == '|':
            return evaluate(node[1], values) or evaluate(node[2], values)
        if kind == '->':
            return (not evaluate(node[1], values)) or evaluate(node[2], values)
