    minterms = []
    n_vars = len(var_list)
    for idx in range(1 << n_vars):
        values = {}
        for i, name in enumerate(var_list):
            values[name] = bool((idx >> (n_vars - 1 - i)) & 1)
        if evaluate(ast, values):
