def bool_minterms(expr):
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c == ' ':
            i += 1
            continue
        if 'a' <= c <= 'z':
            j = i + 1
            while j < n and 'a' <= expr[j] <= 'z':
                j += 1
            tokens.append(expr[i:j])
            i = j
            continue
        if '0' <= c <= '9':
            j = i + 1
            while j < n and '0' <= expr[j] <= '9':
                j += 1
            run = expr[i:j]
            if run == '0' or run == '1':
                tokens.append(run)
                i = j
                continue
            return None
        if c == '-':
            if i + 1 < n and expr[i + 1] == '>':
                tokens.append('->')
                i += 2
                continue
            return None
        if c in '!&^|()':
            tokens.append(c)
            i += 1
            continue
        return None
    if not tokens:
        return None

    pos = 0

    def peek():
        if pos < len(tokens):
            return tokens[pos]
        return None

    def advance():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def parse_implication():
        left = parse_or()
        if peek() == '->':
            advance()
            right = parse_implication()
            return ('->', left, right)
        return left

    def parse_or():
        left = parse_xor()
        while peek() == '|':
            advance()
            right = parse_xor()
            left = ('|', left, right)
        return left

    def parse_xor():
        left = parse_and()
        while peek() == '^':
            advance()
            right = parse_and()
            left = ('^', left, right)
        return left

    def parse_and():
        left = parse_unary()
        while peek() == '&':
            advance()
            right = parse_unary()
            left = ('&', left, right)
        return left

    def parse_unary():
        if peek() == '!':
            advance()
            operand = parse_unary()
            return ('!', operand)
        return parse_primary()

    def parse_primary():
        tok = peek()
        if tok == '(':
            advance()
            node = parse_implication()
            if peek() != ')':
                raise ValueError('expected )')
            advance()
            return node
        if tok is None:
            raise ValueError('unexpected end')
